package com.holonplatform.multitenancy.demo.config;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;
import org.springframework.security.web.SecurityFilterChain;

/**
 * Spring Security configuration for the demo application.
 *
 * <p>Spring Boot 4.x (Spring Security 7.x) defaults to <em>deny-all</em> when no
 * {@link SecurityFilterChain} bean is present. This configuration permits the
 * Vaadin routes, H2 console, and webhook endpoints while still allowing
 * the Holon tenant filters (registered at orders -100 and -50) to run first.</p>
 */
@Configuration
@EnableWebSecurity
public class DemoSecurityConfig {

    @Bean
    public SecurityFilterChain securityFilterChain(HttpSecurity http) throws Exception {
        http
            // Vaadin requires its own CSRF handling; disable Spring's CSRF for Vaadin paths
            .csrf(csrf -> csrf
                .ignoringRequestMatchers("/VAADIN/**", "/vaadinServlet/**", "/h2-console/**")
            )
            // Allow the H2 in-browser console to render inside frames
            .headers(headers -> headers
                .frameOptions(frame -> frame.sameOrigin())
            )
            .authorizeHttpRequests(auth -> auth
                // H2 console (development only)
                .requestMatchers("/h2-console/**").permitAll()
                // Vaadin internal routes and static resources
                .requestMatchers(
                    "/VAADIN/**",
                    "/vaadinServlet/**",
                    "/frontend/**",
                    "/icons/**",
                    "/images/**",
                    "/favicon.ico",
                    "/manifest.webmanifest",
                    "/sw.js",
                    "/offline.html"
                ).permitAll()
                // WhatsApp webhook endpoint
                .requestMatchers("/webhook/**").permitAll()
                // All other requests (Vaadin views are protected by Holon navigation guards)
                .anyRequest().permitAll()
            )
            // Use HTTP Basic for the demo — override in production with form login or OAuth2
            .httpBasic(basic -> {});

        return http.build();
    }
}

package com.holonplatform.multitenancy.demo.ui;

import com.holonplatform.vaadin.flow.i18n.LocalizationProvider;
import com.holonplatform.multitenant.vaadin.TenantUiContext;
import com.holonplatform.vaadin.flow.vaadinplus.components.AppBar;
