import com.vaadin.flow.component.dependency.StyleSheet;
import com.vaadin.flow.router.Layout;

/**
 * Root application layout for the Holon SaaS Demo.
 *
 * <h2>Structure</h2>
 * <ul>
 *   <li>Navbar → {@link AppBar} with a tenant badge and user avatar menu</li>
 *   <li>Drawer → {@link SideNavBuilder} grouped navigation covering every
 *       module in the framework</li>
 * </ul>
 *
 * <h2>Navigation groups</h2>
 * <ul>
 *   <li><strong>Home</strong> — Dashboard (KPI overview)</li>
 *   <li><strong>Tenant</strong> — Tenant Context info, Onboarding wizard</li>
 *   <li><strong>Operations</strong> — Audit log, Settings, Rate limiter</li>
 *   <li><strong>Users &amp; Billing</strong> — User management, Subscription / invoices</li>
 *   <li><strong>Access Guards</strong> — Feature-gated view, Plan-gated view, Upgrade page</li>
 *   <li><strong>Admin Console</strong> — Links to the built-in TenantAdmin module</li>
 * </ul>
 *
 * <p>Every label uses {@link LocalizationProvider#localize(String, String)}
 * so the layout is fully i18n-ready.
 */
@StyleSheet("context://demo.css")
@Layout("/")
public class DemoMainLayout extends AppLayout {

    public DemoMainLayout() {

        // ── Top bar ─────���──────────────────────────────────────────────────────
        var appBar = new AppBar();

        var logoIcon = VaadinIcon.ROCKET.create();
        var logoText = new Span(LocalizationProvider.localize("Holon SaaS Demo", "demo.app.name"));
        logoText.addClassName("demo__app-name");
        appBar.addToStart(logoIcon, logoText);

        // Current tenant badge — resolved from VaadinSession via TenantUiContext
        var tenantId  = TenantUiContext.currentTenantId().orElse("(no tenant)");
        var tenantBadge = new Span(tenantId);
        tenantBadge.addClassName("demo__tenant-badge");
        appBar.addToEnd(tenantBadge);

        // User avatar with context menu
        var avatar   = new Avatar("Admin");
        var userMenu = new ContextMenu(avatar);
        userMenu.setOpenOnClick(true);
        userMenu.addItem(LocalizationProvider.localize("Profile", "demo.menu.profile"));
        userMenu.addItem(LocalizationProvider.localize("Sign out", "demo.menu.signout"));
        appBar.addToEnd(avatar);

        // ── Sidebar ────────────────────────────────────────────────────────────
        var nav = SideNavBuilder.create()
                .withSearch(LocalizationProvider.localize("Filter menu…", "demo.nav.search"));

        // Home
        nav.withNavItem(LocalizationProvider.localize("Home", "demo.nav.home"))
                .prefixComponent(VaadinIcon.HOME.create())
                .withItems(
                        new SideNavItem(
                                LocalizationProvider.localize("Dashboard", "demo.nav.dashboard"),
                                DashboardView.class,
                                VaadinIcon.DASHBOARD.create()))
                .add();

        // Tenant
        nav.withNavItem(LocalizationProvider.localize("Tenant", "demo.nav.tenant"))
                .prefixComponent(VaadinIcon.BUILDING.create())
                .withItems(
                        new SideNavItem(
                                LocalizationProvider.localize("Tenant Context", "demo.nav.context"),
                                TenantContextView.class,
                                VaadinIcon.INFO_CIRCLE.create()),
                        new SideNavItem(
                                LocalizationProvider.localize("Onboarding", "demo.nav.onboarding"),
                                OnboardingView.class,
                                VaadinIcon.PLUS_CIRCLE.create()))
                .add();

        // Operations
        nav.withNavItem(LocalizationProvider.localize("Operations", "demo.nav.operations"))
                .prefixComponent(VaadinIcon.COG_O.create())
                .withItems(
                        new SideNavItem(
                                LocalizationProvider.localize("Audit Log", "demo.nav.audit"),
                                AuditView.class,
                                VaadinIcon.RECORDS.create()),
                        new SideNavItem(
                                LocalizationProvider.localize("Settings", "demo.nav.settings"),
                                SettingsView.class,
                                VaadinIcon.SLIDERS.create()),
                        new SideNavItem(
                                LocalizationProvider.localize("Rate Limiter", "demo.nav.rate"),
                                RateLimiterView.class,
                                VaadinIcon.STOPWATCH.create()))
                .add();

        // Users & Billing
        nav.withNavItem(LocalizationProvider.localize("Users & Billing", "demo.nav.business"))
                .prefixComponent(VaadinIcon.USERS.create())
                .withItems(
                        new SideNavItem(
                                LocalizationProvider.localize("Users", "demo.nav.users"),
                                UsersView.class,
                                VaadinIcon.USERS.create()),
                        new SideNavItem(
                                LocalizationProvider.localize("Billing", "demo.nav.billing"),
                                BillingView.class,
                                VaadinIcon.CREDIT_CARD.create()))
                .add();

        // Access Guards
        nav.withNavItem(LocalizationProvider.localize("Access Guards", "demo.nav.guards"))
                .prefixComponent(VaadinIcon.LOCK.create())
                .withItems(
                        new SideNavItem(
                                LocalizationProvider.localize("Feature Gated (ADVANCED_REPORTS)", "demo.nav.feature"),
                                FeatureGatedView.class,
                                VaadinIcon.STAR.create()),
                        new SideNavItem(
                                LocalizationProvider.localize("Plan Gated (PROFESSIONAL+)", "demo.nav.plan"),
                                ProPlanView.class,
                                VaadinIcon.TROPHY.create()),
                        new SideNavItem(
                                LocalizationProvider.localize("Upgrade Required", "demo.nav.upgrade"),
                                UpgradeView.class,
                                VaadinIcon.ARROW_UP.create()))
                .add();

        // Admin Console
        nav.withNavItem(LocalizationProvider.localize("Admin Console", "demo.nav.admin"))
                .prefixComponent(VaadinIcon.SHIELD.create())
                .withItems(
                        new SideNavItem(
                                LocalizationProvider.localize("Tenant Admin", "demo.nav.tenant.admin"),
                                TenantAdminDemoView.class,
                                VaadinIcon.EDIT.create()))
                .add();

        // ── Assemble ───────────────────────────────────────────────────────────
        setPrimarySection(Section.DRAWER);
        addToNavbar(true, appBar);
        addToDrawer(buildDrawerHeader(), nav.buildWrapper());
    }

    private VerticalLayout buildDrawerHeader() {
        var icon  = VaadinIcon.ROCKET.create();
        icon.setSize("36px");

        var title = new Span(LocalizationProvider.localize("Holon SaaS", "demo.drawer.title"));
        title.addClassName("demo__drawer-title");

        var sub = new Span(LocalizationProvider.localize("Framework Demo", "demo.drawer.subtitle"));
        sub.addClassName("demo__drawer-subtitle");

        var header = new VerticalLayout(icon, title, sub);
        header.setAlignItems(FlexComponent.Alignment.CENTER);
        header.setSpacing(false);
        header.setPadding(true);
        header.addClassName("demo__drawer-header");
        return header;
    }
}

