import com.vaadin.flow.theme.lumo.LumoUtility;

import java.time.YearMonth;
import java.time.ZoneOffset;
import java.time.format.DateTimeFormatter;
import java.util.List;
import java.util.Map;

/**
 * Demo view for the WhatsApp integration module, accessible from the main
 * demo navigation at {@code /whatsapp-demo}.
 *
 * <h2>What this view demonstrates</h2>
 * <ul>
 *   <li>Integration status (DEMO mode vs. real Meta credentials)</li>
 *   <li>Cost breakdown — free vs charged conversation types</li>
 *   <li>Quick-send: text message and template message</li>
 *   <li>Lazy recent-messages grid (paged via {@code grid.setItems(query -&gt; …)})</li>
 *   <li>Available templates with their billing category</li>
 *   <li>Service window indicator with the 24-h free-reply explanation</li>
 * </ul>
 *
 * <h2>Lazy loading</h2>
 * The message grid uses Vaadin's unknown-item-count mode. The constructor only
 * builds the UI structure; data is loaded in {@link #onAttach(AttachEvent)}.
 *
 * <h2>Navigation to the full management UI</h2>
 * The WhatsApp management section is available at {@code /whatsapp} and uses its
 * own {@code WhatsAppManageLayout} shell. This demo view is a convenience showcase
 * inside the main demo layout.
 */
@Route(value = "whatsapp-demo", layout = DemoMainLayout.class)
@PageTitle("WhatsApp Integration Demo")
public class WhatsAppDemoView extends VerticalLayout {

    private static final DateTimeFormatter FMT =
            DateTimeFormatter.ofPattern("dd MMM HH:mm").withZone(ZoneOffset.UTC);

    private final TenantWhatsAppService service;

    // ── KPI spans ─────────────────────────────────────────────────────────────
    private final Span totalSpan   = new Span("–");
    private final Span freeSpan    = new Span("–");
    private final Span chargedSpan = new Span("–");
    private final Span windowsSpan = new Span("–");
    private final Span costSpan    = new Span("$–");
    private final ProgressBar freeBar = new ProgressBar(0, 100);

    // ── Quick-send: text ──────────────────────────────────────────────────────
    private final TextField    toField      = new TextField("Recipient phone (E.164)");
    private final TextField    messageField = new TextField("Text message");

    // ── Quick-send: template ──────────────────────────────────────────────────
    private final TextField    templateToField = new TextField("Recipient phone (E.164)");
    private final Select<String> templateSelect = new Select<>();
    private final TextField    paramField      = new TextField("{{1}} substitution");

    // ── Lazy messages grid ────────────────────────────────────────────────────
    private final Grid<WhatsAppMessage> msgGrid = new Grid<>(WhatsAppMessage.class, false);

    // ── Templates grid ────────────────────────────────────────────────────────
    private final Grid<WhatsAppTemplate> tplGrid = new Grid<>(WhatsAppTemplate.class, false);

    public WhatsAppDemoView(TenantWhatsAppService service) {
        this.service = service;
        setSizeFull();
        setPadding(true);
        setSpacing(true);
        // Constructor: structure only, no service calls
        add(
                buildPageHeader(),
                buildStatusBanner(),
                buildKpiCards(),
                buildQuickSendPanel(),
                buildTemplatePanel(),
                buildMessagesGrid(),
                buildCostEducation()
        );
    }

    // ── Lazy init ─────────────────────────────────────────────────────────────

    @Override
    protected void onAttach(AttachEvent event) {
        super.onAttach(event);
        refreshKpis();
        msgGrid.getDataCommunicator().reset();
        loadTemplates();
    }

    // ── Page header ───────────────────────────────────────────────────────────

    private HorizontalLayout buildPageHeader() {
        H2 title = new H2(" WhatsApp Integration");
        title.addClassNames(LumoUtility.Margin.NONE);

        Button refreshBtn = new Button("↻ Refresh", e -> {
            refreshKpis();
            msgGrid.getDataCommunicator().reset();
        });
        refreshBtn.addThemeVariants(ButtonVariant.LUMO_TERTIARY);

        Anchor managementLink = new Anchor("/whatsapp", "→ Full management UI");
        managementLink.addClassNames(LumoUtility.FontSize.SMALL);

        HorizontalLayout h = new HorizontalLayout(title, managementLink, refreshBtn);
        h.setWidthFull();
        h.setAlignItems(Alignment.BASELINE);
        h.setJustifyContentMode(JustifyContentMode.BETWEEN);
        return h;
    }

    // ── Status banner ─────────────────────────────────────────────────────────

    private Div buildStatusBanner() {
        boolean hasCredentials = false; // auto-detect would require injecting properties
        String mode = hasCredentials
                ? "✅ Connected to Meta WhatsApp Cloud API (SHARED mode)"
                : "⚠ Running in DEMO mode — messages are logged only (no real API credentials configured)";

        Paragraph p = new Paragraph(mode);
        p.addClassNames(
                hasCredentials ? LumoUtility.TextColor.SUCCESS : LumoUtility.TextColor.ERROR,
                LumoUtility.Margin.NONE);

        Paragraph tip = new Paragraph(
                "To connect a real WhatsApp Business account, set "
                        + "holon.tenant.whatsapp.shared.access-token, .phone-number-id, and .waba-id "
                        + "in application.properties.");
        tip.addClassNames(LumoUtility.FontSize.SMALL, LumoUtility.TextColor.SECONDARY,
                LumoUtility.Margin.NONE);

        Div banner = new Div(p, tip);
        banner.addClassNames(LumoUtility.Padding.MEDIUM, LumoUtility.BorderRadius.MEDIUM,
                LumoUtility.Background.CONTRAST_5);
        banner.setWidthFull();
        return banner;
    }

    // ── KPI cards ─────────────────────────────────────────────────────────────

    private VerticalLayout buildKpiCards() {
        applyBadge(totalSpan,   "badge");
        applyBadge(freeSpan,    "badge success");
        applyBadge(chargedSpan, "badge contrast");
        applyBadge(windowsSpan, "badge");
        applyBadge(costSpan,    "badge error");

        FlexLayout cards = new FlexLayout(
                kpiCard("Total messages",        totalSpan),
                kpiCard("Free messages",          freeSpan),
                kpiCard("Charged messages",       chargedSpan),
                kpiCard("Open service windows ", windowsSpan),
                kpiCard("Est. cost (USD)",         costSpan)
        );
        cards.setFlexWrap(FlexLayout.FlexWrap.WRAP);
        cards.setWidthFull();
        cards.getStyle().set("gap", "var(--lumo-space-m)");

        freeBar.setWidthFull();
        Paragraph barLabel = new Paragraph(
                "Free traffic ratio — SERVICE (user-initiated) + UTILITY templates are free");
        barLabel.addClassNames(LumoUtility.Margin.NONE, LumoUtility.FontSize.SMALL,
                LumoUtility.TextColor.SECONDARY);
        Div barCard = new Div(barLabel, freeBar);
        barCard.addClassNames(LumoUtility.Padding.MEDIUM, LumoUtility.BorderRadius.MEDIUM,
                LumoUtility.Background.CONTRAST_5);
        barCard.setWidthFull();

        VerticalLayout l = new VerticalLayout(cards, barCard);
        l.setPadding(false);
        l.setSpacing(true);
        l.setWidthFull();
        return l;
    }

    private static void applyBadge(Span span, String theme) {
        span.getElement().getThemeList().add(theme);
        span.addClassNames(LumoUtility.FontSize.XLARGE, LumoUtility.FontWeight.BOLD);
    }

    private Div kpiCard(String label, Span valueSpan) {
        Paragraph l = new Paragraph(label);
        l.addClassNames(LumoUtility.Margin.NONE, LumoUtility.FontSize.SMALL,
                LumoUtility.TextColor.SECONDARY);
        Div card = new Div(l, valueSpan);
        card.addClassNames(LumoUtility.Padding.MEDIUM, LumoUtility.BorderRadius.MEDIUM,
                LumoUtility.Background.CONTRAST_5);
        card.setWidth("200px");
        return card;
    }

    // ── Quick-send: plain text ────────────────────────────────────────────────

    private Div buildQuickSendPanel() {
        toField.setPlaceholder("+15551234567");
        toField.setWidth("220px");
        messageField.setPlaceholder("Enter your message text…");
        messageField.setWidth("360px");

        Button sendTextBtn = new Button("Send text message", e -> doSendText());
        sendTextBtn.addThemeVariants(ButtonVariant.LUMO_PRIMARY, ButtonVariant.LUMO_SUCCESS);

        Paragraph hint = new Paragraph(
                " The service first checks if a 24-hour free service window is open for the "
                        + "recipient phone. If yes → plain text (FREE). If no → UTILITY template (also FREE).");
        hint.addClassNames(LumoUtility.FontSize.SMALL, LumoUtility.TextColor.SECONDARY,
                LumoUtility.Margin.NONE);

        HorizontalLayout row = new HorizontalLayout(toField, messageField, sendTextBtn);
        row.setAlignItems(Alignment.END);

        Div card = new Div(new H3("✉️ Quick Send — Text"), row, hint);
        card.addClassNames(LumoUtility.Padding.MEDIUM, LumoUtility.BorderRadius.MEDIUM,
                LumoUtility.Background.CONTRAST_5);
        card.setWidthFull();
        return card;
    }

    private void doSendText() {
        String to   = toField.getValue().trim();
        String text = messageField.getValue().trim();
        if (to.isBlank() || text.isBlank()) {
            Notification.show("Fill in both fields.", 2500, Notification.Position.MIDDLE);
            return;
        }
        String tenantId = TenantContext.currentTenantId().orElse("demo");
        try {
            WhatsAppMessage sent = service.sendTextMessage(tenantId, to, text);
            boolean free = sent.freeConversation();
            Notification n = Notification.show(
                    free ? "✅ Sent FREE (open service window)"
                         : "✅ Sent — " + sent.conversationType().name() + " (free category)",
                    4000, Notification.Position.BOTTOM_END);
            n.addThemeVariants(NotificationVariant.LUMO_SUCCESS);
            messageField.clear();
            refreshKpis();
            msgGrid.getDataCommunicator().reset();
        } catch (Exception ex) {
            Notification n = Notification.show("Error: " + ex.getMessage(),
                    5000, Notification.Position.MIDDLE);
            n.addThemeVariants(NotificationVariant.LUMO_ERROR);
        }
    }

    // ── Quick-send: template ──────────────────────────────────────────────────

    private Div buildTemplatePanel() {
        templateToField.setPlaceholder("+15551234567");
        templateToField.setWidth("220px");

        templateSelect.setLabel("Template");
        templateSelect.setWidth("240px");
        templateSelect.setPlaceholder("Select a template…");

        paramField.setPlaceholder("Optional {{1}} parameter");
        paramField.setWidth("240px");

        Button sendTplBtn = new Button("Send template", e -> doSendTemplate());
        sendTplBtn.addThemeVariants(ButtonVariant.LUMO_PRIMARY);

        Paragraph hint = new Paragraph(
                " UTILITY templates are FREE — use them for all transactional messages. "
                        + "MARKETING templates count against your plan's monthly quota.");
        hint.addClassNames(LumoUtility.FontSize.SMALL, LumoUtility.TextColor.SECONDARY,
                LumoUtility.Margin.NONE);

        HorizontalLayout row = new HorizontalLayout(templateToField, templateSelect, paramField, sendTplBtn);
        row.setAlignItems(Alignment.END);

        Div card = new Div(new H3(" Quick Send — Template"), row, hint);
        card.addClassNames(LumoUtility.Padding.MEDIUM, LumoUtility.BorderRadius.MEDIUM,
                LumoUtility.Background.CONTRAST_5);
        card.setWidthFull();
        return card;
    }

    private void doSendTemplate() {
        String to   = templateToField.getValue().trim();
        String name = templateSelect.getValue();
        if (to.isBlank() || name == null || name.isBlank()) {
            Notification.show("Select a template and enter a phone number.", 2500,
                    Notification.Position.MIDDLE);
            return;
        }
        String param = paramField.getValue().isBlank() ? "Demo" : paramField.getValue().trim();
        String tenantId = TenantContext.currentTenantId().orElse("demo");
        try {
            WhatsAppMessage sent = service.sendTemplateMessage(tenantId, to, name, "en_US",
                    Map.of("1", param));
            String category = sent.conversationType().name();
            boolean free = sent.freeConversation();
            Notification n = Notification.show(
                    "✅ Template '" + name + "' sent — " + category
                            + (free ? " (free)" : " (charged)"),
                    4000, Notification.Position.BOTTOM_END);
            n.addThemeVariants(free ? NotificationVariant.LUMO_SUCCESS : NotificationVariant.LUMO_CONTRAST);
            templateToField.clear();
            refreshKpis();
            msgGrid.getDataCommunicator().reset();
        } catch (Exception ex) {
            Notification n = Notification.show("Error: " + ex.getMessage(),
                    5000, Notification.Position.MIDDLE);
            n.addThemeVariants(NotificationVariant.LUMO_ERROR);
        }
    }

    // ── Lazy messages grid ────────────────────────────────────────────────────

    private Div buildMessagesGrid() {
        msgGrid.addColumn(m -> FMT.format(m.createdAt()))
                .setHeader("Time (UTC)").setWidth("160px");
        msgGrid.addColumn(WhatsAppMessage::to)
                .setHeader("To").setAutoWidth(true);
        msgGrid.addColumn(m -> m.type().name())
                .setHeader("Type").setWidth("100px");
        msgGrid.addColumn(m -> m.conversationType().name())
                .setHeader("Category").setWidth("130px");
        msgGrid.addColumn(m -> m.freeConversation() ? "✅ Free" : " Charged")
                .setHeader("Cost").setWidth("110px");
        msgGrid.addColumn(m -> m.status().name())
                .setHeader("Status").setWidth("110px");
        msgGrid.addColumn(m -> truncate(m.content(), 60))
                .setHeader("Content").setFlexGrow(1);

        // ── Lazy data provider (unknown-item-count mode) ──────────────────────
        msgGrid.setItems(query -> {
            String tenantId = TenantContext.currentTenantId().orElse("demo");
            return service.listMessages(tenantId, query.getOffset(), query.getLimit()).stream();
        });
        msgGrid.setHeight("360px");
        msgGrid.setWidthFull();

        Div card = new Div(new H3(" Message Log (lazy — newest first)"), msgGrid);
        card.addClassNames(LumoUtility.Padding.MEDIUM, LumoUtility.BorderRadius.MEDIUM,
                LumoUtility.Background.CONTRAST_5);
        card.setWidthFull();
        return card;
    }

    // ── Cost education panel ──────────────────────────────────────────────────

    private Div buildCostEducation() {
        Div card = new Div();
        card.addClassNames(LumoUtility.Padding.MEDIUM, LumoUtility.BorderRadius.MEDIUM,
                LumoUtility.Background.CONTRAST_5);
        card.setWidthFull();
        card.add(new H3(" How costs are reduced in this framework"));

        UnorderedList list = new UnorderedList();
        list.add(tip("<b>SERVICE conversations</b> (user-initiated): customer messages you first → "
                + "FREE 24-hour reply window opens. Any message sent inside that window is <em>completely free</em>."));
        list.add(tip("<b>UTILITY templates</b>: transactional messages (order updates, reminders) → "
                + "FREE since Meta's 2024 pricing simplification.  No cap."));
        list.add(tip("<b>MARKETING templates</b>: promotional messages → charged per conversation. "
                + "Gated by plan quota (FREE=50/mo, STARTER=200, PRO=2000, ENTERPRISE=∞)."));
        list.add(tip("<b>ConversationWindowTracker</b>: persists open windows in memory. "
                + "Every outbound send checks the tracker first before deciding to use a template."));
        list.add(tip("<b>Dashboard</b>: live free-traffic ratio bar + cost estimate so operators "
                + "can continuously monitor and optimise sending patterns."));
        list.add(tip("<b>SHARED WABA mode</b>: all tenants on one WhatsApp Business Account "
                + "→ lower infrastructure overhead for small-plan tenants."));
        card.add(list);
        return card;
    }

    private static ListItem tip(String html) {
        ListItem item = new ListItem();
        item.getElement().setProperty("innerHTML", html);
        item.addClassNames(LumoUtility.Margin.Bottom.XSMALL);
        return item;
    }

    // ── Data refresh helpers ──────────────────────────────────────────────────

    private void refreshKpis() {
        String tenantId = TenantContext.currentTenantId().orElse("demo");
        WhatsAppUsageStats stats = service.getUsageStats(tenantId, YearMonth.now());

        totalSpan.setText(String.valueOf(stats.totalMessages()));
        freeSpan.setText(String.valueOf(stats.freeMessages()));
        chargedSpan.setText(String.valueOf(stats.chargedMessages()));
        windowsSpan.setText(String.valueOf(stats.openWindows()));
        costSpan.setText("$%.4f".formatted(stats.estimatedCostUsd()));
        freeBar.setValue(stats.totalMessages() == 0 ? 100.0 : stats.freePercentage());
    }

    private void loadTemplates() {
        String tenantId = TenantContext.currentTenantId().orElse("demo");
        List<WhatsAppTemplate> templates = service.listTemplates(tenantId);
        List<String> names = templates.stream()
                .filter(WhatsAppTemplate::isApproved)
                .map(t -> t.name() + " [" + costTag(t.category()) + "]")
                .toList();
        templateSelect.setItems(names);
        // raw names for the actual send call
        tplGrid.setItems(templates);
    }

    private static String costTag(WhatsAppConversationType cat) {
        if (cat == null) return "?";
        return switch (cat) {
            case UTILITY -> "free";
            case AUTHENTICATION -> "auth/charged";
            case MARKETING -> "MARKETING/charged";
            default -> cat.name().toLowerCase();
        };
    }

    private static String truncate(String s, int max) {
        if (s == null) return "";
        return s.length() > max ? s.substring(0, max) + "…" : s;
    }
}

$root = "C:\Users\sxp267\IdeaProjects\holon-saas"
$extensions = @("*.java","*.imports","*.xml","*.properties","*.yaml","*.yml")
$fixed = 0

foreach ($ext in $extensions) {
    $files = Get-ChildItem -Path $root -Recurse -Include $ext -File
    foreach ($file in $files) {
        $bytes = [System.IO.File]::ReadAllBytes($file.FullName)
        if ($bytes.Length -ge 3 -and $bytes[0] -eq 0xEF -and $bytes[1] -eq 0xBB -and $bytes[2] -eq 0xBF) {
            $newBytes = $bytes[3..($bytes.Length - 1)]
            [System.IO.File]::WriteAllBytes($file.FullName, $newBytes)
            $fixed++
            Write-Output "Fixed BOM: $($file.FullName)"
        }
    }
}

Write-Output "Total files with BOM fixed: $fixed"

$root = "C:\Users\sxp267\IdeaProjects\holon-saas"
$n = 0
$files = Get-ChildItem "$root\*" -Recurse -File | Where-Object { $_.Extension -in @('.java','.xml','.imports','.properties','.yaml','.yml') }
Write-Output "Scanning $($files.Count) files..."
foreach ($f in $files) {
    $bytes = [System.IO.File]::ReadAllBytes($f.FullName)
    if ($bytes.Length -ge 3 -and $bytes[0] -eq 239 -and $bytes[1] -eq 187 -and $bytes[2] -eq 191) {
        $stripped = New-Object byte[] ($bytes.Length - 3)
        [System.Array]::Copy($bytes, 3, $stripped, 0, $bytes.Length - 3)
        [System.IO.File]::WriteAllBytes($f.FullName, $stripped)
        $n++
        Write-Output "Fixed: $($f.FullName)"
    }
}
Write-Output "Done. Fixed $n files."

import os

root = r'C:\Users\sxp267\IdeaProjects\holon-saas'
exts = {'.java', '.xml', '.imports', '.properties', '.yaml', '.yml'}
fixed = 0

for dirpath, dirnames, filenames in os.walk(root):
    dirnames[:] = [d for d in dirnames if not d.startswith('.') and d != 'target']
    for fname in filenames:
        if any(fname.endswith(e) for e in exts):
            fpath = os.path.join(dirpath, fname)
            try:
                with open(fpath, 'rb') as f:
                    data = f.read()
                if data.startswith(b'\xef\xbb\xbf'):
                    with open(fpath, 'wb') as f:
                        f.write(data[3:])
                    fixed += 1
                    print('Fixed:', fpath)
            except Exception as e:
                print('Error:', fpath, str(e))

print(f'Total fixed: {fixed}')

package com.holonplatform.multitenant.admin;

import com.holonplatform.multitenant.admin.service.InMemoryTenantAdminService;
import com.holonplatform.multitenant.admin.service.TenantAdminService;
import org.springframework.boot.autoconfigure.AutoConfiguration;
import org.springframework.boot.autoconfigure.condition.ConditionalOnMissingBean;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.ComponentScan;

/**
 * Spring Boot auto-configuration for the tenant-admin module.
 *
 * <p>Registers the {@link InMemoryTenantAdminService} as the default
 * {@link TenantAdminService} implementation when no other bean of that type
 * is present in the application context.</p>
 *
 * <p>To use a custom persistence-backed implementation, declare a
 * {@code @Bean} of type {@link TenantAdminService} in your application
 * configuration — this auto-configuration will back off automatically.</p>
 */
@AutoConfiguration
@ComponentScan(basePackages = "com.holonplatform.multitenant.admin")
public class TenantAdminAutoConfiguration {

    @Bean
    @ConditionalOnMissingBean(TenantAdminService.class)
    public TenantAdminService tenantAdminService() {
        return new InMemoryTenantAdminService();
    }
}

