    static class AuditedServiceImpl implements AuditedService {

        @Override
        @Audited(action = AuditAction.UPDATE, resourceType = "Item", resourceIdExpression = "#id")
        public void doUpdate(String id) { /* OK */ }

        @Override
        @Audited(action = AuditAction.DELETE, logOnFailure = true)
        public void doFailingOp() { throw new RuntimeException("boom"); }

        @Override
        @Audited(action = AuditAction.DELETE, logOnFailure = false)
        public void doFailingOpNoLog() { throw new RuntimeException("silent"); }
    }

    @Configuration
    @EnableAspectJAutoProxy
    static class TestConfig {

        @Bean
        InMemoryTenantAuditService tenantAuditService() {
            return new InMemoryTenantAuditService();
        }

        @Bean
        ActorResolver actorResolver() {
            return () -> ActorResolver.SYSTEM;
        }

        @Bean
        com.holonplatform.multitenant.audit.internal.AuditAspect auditAspect(
                TenantAuditService s, ActorResolver r) {
            return new com.holonplatform.multitenant.audit.internal.AuditAspect(s, r);
        }

        @Bean
        AuditedService auditedService() {
            return new AuditedServiceImpl();
        }
    }
}

package com.holonplatform.multitenant.vaadin.view.signup;

import com.holonplatform.multitenant.TenantDetails;
import com.holonplatform.multitenant.signup.SignupException;
import com.holonplatform.multitenant.signup.SignupRequest;
import com.holonplatform.multitenant.signup.SignupService;
import com.vaadin.flow.component.Key;
import com.vaadin.flow.component.UI;
import com.vaadin.flow.component.button.Button;
import com.vaadin.flow.component.button.ButtonVariant;
import com.vaadin.flow.component.formlayout.FormLayout;
import com.vaadin.flow.component.html.Anchor;
import com.vaadin.flow.component.html.H1;
import com.vaadin.flow.component.html.Paragraph;
import com.vaadin.flow.component.notification.Notification;
import com.vaadin.flow.component.notification.NotificationVariant;
import com.vaadin.flow.component.orderedlayout.VerticalLayout;
import com.vaadin.flow.component.textfield.EmailField;
import com.vaadin.flow.component.textfield.PasswordField;
import com.vaadin.flow.component.textfield.TextField;

import java.util.Objects;

/**
 * Ready-to-use public sign-up page: collects a company name, workspace id, owner
 * email and password, then delegates the entire "create tenant + owner account" flow
 * to {@link SignupService}.
 *
 * <p>This class deliberately does <strong>not</strong> declare {@code @Route}: an
 * implementing application only needs a minimal subclass supplying the route,
 * page title and (optionally) a link to its own login view:
 *
 * <pre>{@code
 * @Route("signup")
 * @PageTitle("Sign up")
 * @AnonymousAllowed
 * public class SignupView extends AbstractSignupView {
 *     public SignupView(SignupService signupService) {
 *         super(signupService);
 *     }
 * }
 * }</pre>
 *
 * <p>Override {@link #loginRoute()} to point the "already have a workspace?" link at a
 * different navigation target, and {@link #onSignupSuccess(TenantDetails, String)} to
 * customise the post-signup navigation/message.
 */
public abstract class AbstractSignupView extends VerticalLayout {

    private final SignupService signupService;

    private final TextField companyName = new TextField("Company / workspace name");
    private final TextField workspaceId = new TextField("Workspace ID (URL slug)");
    private final EmailField email = new EmailField("Your email");
    private final PasswordField password = new PasswordField("Password");
    private final PasswordField confirmPassword = new PasswordField("Confirm password");

    protected AbstractSignupView(SignupService signupService) {
        this.signupService = Objects.requireNonNull(signupService);

        setSizeFull();
        setAlignItems(Alignment.CENTER);
        setJustifyContentMode(JustifyContentMode.CENTER);

        H1 title = new H1("Create your workspace");
        Paragraph subtitle = new Paragraph(
                "You'll become the owner of a new tenant and can invite teammates afterwards.");

        workspaceId.setHelperText("Lowercase letters, numbers and hyphens only, e.g. 'acme-corp'.");
        companyName.addValueChangeListener(e -> {
            if (workspaceId.isEmpty() && e.getValue() != null && !e.getValue().isBlank()) {
                workspaceId.setValue(SignupService.slugify(e.getValue()));
            }
        });

        Button submit = new Button("Create workspace", e -> submit());
        submit.addThemeVariants(ButtonVariant.LUMO_PRIMARY);
        submit.addClickShortcut(Key.ENTER);

        FormLayout form = new FormLayout(companyName, workspaceId, email, password, confirmPassword);
        form.setMaxWidth("420px");

        Anchor toLogin = new Anchor(loginRoute(), "Already have a workspace? Sign in");

        add(title, subtitle, form, submit, toLogin);
    }

    /** Navigation target for the "already have a workspace? Sign in" link. Defaults to {@code "login"}. */
    protected String loginRoute() {
        return "login";
    }

    /**
     * Called after a successful sign-up. The default implementation shows a success
     * notification with the login hint ({@code tenantId/email}) and navigates to
     * {@link #loginRoute()}. Override to customise.
     */
    protected void onSignupSuccess(TenantDetails tenant, String ownerEmail) {
        Notification.show("Workspace '" + tenant.tenantId()
                        + "' created! Sign in with " + tenant.tenantId() + "/" + ownerEmail,
                        6000, Notification.Position.MIDDLE)
                .addThemeVariants(NotificationVariant.LUMO_SUCCESS);
        UI.getCurrent().navigate(loginRoute());
    }

    private void submit() {
        if (password.isEmpty() || !password.getValue().equals(confirmPassword.getValue())) {
            Notification.show("Passwords do not match", 4000, Notification.Position.MIDDLE)
                    .addThemeVariants(NotificationVariant.LUMO_ERROR);
            return;
        }
        if (companyName.isEmpty() || workspaceId.isEmpty() || email.isEmpty()) {
            Notification.show("Please fill in all fields", 4000, Notification.Position.MIDDLE)
                    .addThemeVariants(NotificationVariant.LUMO_ERROR);
            return;
        }

        try {
            String ownerEmail = email.getValue().trim();
            TenantDetails tenant = signupService.signup(
                    SignupRequest.builder(workspaceId.getValue().trim(), ownerEmail, password.getValue())
                            .companyName(companyName.getValue().trim())
                            .build());

            onSignupSuccess(tenant, ownerEmail);
        } catch (SignupException ex) {
            Notification.show(ex.getMessage(), 5000, Notification.Position.MIDDLE)
                    .addThemeVariants(NotificationVariant.LUMO_ERROR);
        }
    }
}

package com.holonplatform.multitenant.vaadin.view.users;

import com.holonplatform.multitenant.TenantContext;
import com.holonplatform.multitenant.invitations.InvitationRequest;
import com.holonplatform.multitenant.invitations.TenantInvitationService;
import com.holonplatform.multitenant.invitations.UserInvitation;
import com.holonplatform.multitenant.invitations.exception.InvitationException;
import com.holonplatform.multitenant.users.TenantRole;
import com.holonplatform.multitenant.users.TenantUser;
import com.holonplatform.multitenant.users.TenantUserService;
import com.holonplatform.multitenant.users.TenantUserStatus;
import com.vaadin.flow.component.Text;
import com.vaadin.flow.component.button.Button;
import com.vaadin.flow.component.button.ButtonVariant;
import com.vaadin.flow.component.combobox.ComboBox;
import com.vaadin.flow.component.dialog.Dialog;
import com.vaadin.flow.component.grid.Grid;
import com.vaadin.flow.component.html.H2;
import com.vaadin.flow.component.notification.Notification;
import com.vaadin.flow.component.notification.NotificationVariant;
import com.vaadin.flow.component.orderedlayout.HorizontalLayout;
import com.vaadin.flow.component.orderedlayout.VerticalLayout;
import com.vaadin.flow.component.textfield.EmailField;

import java.util.List;
import java.util.Objects;

/**
 * Ready-to-use, fully-functional team-management view: lists the current tenant's
 * users and lets the operator invite new teammates, change roles, suspend/reactivate
 * and remove members — all backed directly by {@link TenantUserService} and
 * {@link TenantInvitationService}.
 *
 * <p>This class deliberately does <strong>not</strong> declare {@code @Route}: routing,
 * layout and role-based access control (e.g. {@code @RolesAllowed}) are application
 * concerns (every app has its own {@code MainLayout} and role names). An implementing
 * application only needs a two-line subclass:
 *
 * <pre>{@code
 * @Route(value = "users", layout = MainLayout.class)
 * @PageTitle("Team members")
 * @RolesAllowed({"OWNER", "ADMIN"})
 * public class UsersView extends AbstractTenantUserManagementView {
 *     public UsersView(TenantUserService userService, TenantInvitationService invitationService) {
 *         super(userService, invitationService);
 *     }
 * }
 * }</pre>
 *
 * <p>Override {@link #invitableRoles()} to change which roles can be granted via the
 * invite dialog, or {@link #onInvitationSent(UserInvitation)} to customise the
 * confirmation message (e.g. once a real {@code InvitationSender} is configured).
 */
public abstract class AbstractTenantUserManagementView extends VerticalLayout {

    private final TenantUserService tenantUserService;
    private final TenantInvitationService invitationService;
    private final Grid<TenantUser> grid = new Grid<>(TenantUser.class, false);

    protected AbstractTenantUserManagementView(TenantUserService tenantUserService,
                                                TenantInvitationService invitationService) {
        this.tenantUserService = Objects.requireNonNull(tenantUserService);
        this.invitationService = Objects.requireNonNull(invitationService);

        setSizeFull();

        H2 title = new H2("Team members");
        Button invite = new Button("Invite teammate", e -> openInviteDialog());
        invite.addThemeVariants(ButtonVariant.LUMO_PRIMARY);

        HorizontalLayout toolbar = new HorizontalLayout(title, invite);
        toolbar.setWidthFull();
        toolbar.setAlignItems(Alignment.CENTER);
        toolbar.expand(title);

        configureGrid();

        add(toolbar, grid);
        refresh();
    }

    /**
     * Roles that may be granted through the invite dialog. Defaults to every role
     * except {@link TenantRole#OWNER} (there can only be one owner, created at sign-up).
     * Override to restrict further.
     */
    protected TenantRole[] invitableRoles() {
        return new TenantRole[] {TenantRole.VIEWER, TenantRole.MEMBER, TenantRole.ADMIN};
    }

    /**
     * Called after an invitation has been successfully created. The default
     * implementation shows the raw token (useful without a configured
     * {@code InvitationSender}). Override to show a simpler "invitation sent" message
     * once email delivery is configured.
     */
    protected void onInvitationSent(UserInvitation invitation) {
        notifyOk("Invitation sent (accept link token: " + invitation.token() + ")");
    }

    private void configureGrid() {
        grid.addColumn(TenantUser::effectiveName).setHeader("Name").setAutoWidth(true);
        grid.addColumn(TenantUser::getEmail).setHeader("Email").setAutoWidth(true);
        grid.addColumn(u -> u.getRole().name()).setHeader("Role").setAutoWidth(true);
        grid.addColumn(u -> u.getStatus().name()).setHeader("Status").setAutoWidth(true);
        grid.addComponentColumn(this::rowActions).setHeader("Actions").setAutoWidth(true);
        grid.setSizeFull();
    }

    private HorizontalLayout rowActions(TenantUser user) {
        HorizontalLayout actions = new HorizontalLayout();

        ComboBox<TenantRole> roleBox = new ComboBox<>();
        roleBox.setItems(TenantRole.values());
        roleBox.setValue(user.getRole());
        roleBox.setWidth("140px");
        roleBox.addValueChangeListener(e -> {
            if (e.getValue() != null && e.getValue() != user.getRole()) {
                try {
                    tenantUserService.changeRole(currentTenantId(), user.getUserId(), e.getValue());
                    notifyOk("Role updated");
                    refresh();
                } catch (Exception ex) {
                    notifyError(ex.getMessage());
                    refresh();
                }
            }
        });
        actions.add(roleBox);

        if (user.getStatus() == TenantUserStatus.ACTIVE) {
            Button suspend = new Button("Suspend", e -> {
                try {
                    tenantUserService.suspend(currentTenantId(), user.getUserId());
                    refresh();
                } catch (Exception ex) {
                    notifyError(ex.getMessage());
                }
            });
            actions.add(suspend);
        } else if (user.getStatus() == TenantUserStatus.SUSPENDED) {
            Button reactivate = new Button("Reactivate", e -> {
                try {
                    tenantUserService.activate(currentTenantId(), user.getUserId());
                    refresh();
                } catch (Exception ex) {
                    notifyError(ex.getMessage());
                }
            });
            actions.add(reactivate);
        }

        Button remove = new Button("Remove", e -> {
            try {
                tenantUserService.remove(currentTenantId(), user.getUserId());
                notifyOk("User removed");
                refresh();
            } catch (Exception ex) {
                notifyError(ex.getMessage());
            }
        });
        remove.addThemeVariants(ButtonVariant.LUMO_ERROR, ButtonVariant.LUMO_TERTIARY);
        actions.add(remove);

        return actions;
    }

    private void openInviteDialog() {
        Dialog dialog = new Dialog();
        dialog.setHeaderTitle("Invite a teammate");

        EmailField email = new EmailField("Email");
        ComboBox<TenantRole> role = new ComboBox<>("Role");
        role.setItems(invitableRoles());
        role.setValue(TenantRole.MEMBER);

        Button send = new Button("Send invitation", e -> {
            try {
                UserInvitation invitation = invitationService.invite(
                        InvitationRequest.builder(currentTenantId(), email.getValue())
                                .platformRole(role.getValue())
                                .build());
                onInvitationSent(invitation);
                dialog.close();
            } catch (InvitationException ex) {
                notifyError(ex.getMessage());
            }
        });
        send.addThemeVariants(ButtonVariant.LUMO_PRIMARY);
        Button cancel = new Button("Cancel", e -> dialog.close());

        dialog.add(new VerticalLayout(email, role,
                new Text("Note: configure an InvitationSender bean to email this link automatically — "
                        + "otherwise share /accept-invite?token=<token> manually.")));
        dialog.getFooter().add(cancel, send);
        dialog.open();
    }

    /** Reloads the grid from {@link TenantUserService#findByTenant(String, int, int)}. */
    protected void refresh() {
        List<TenantUser> users = tenantUserService.findByTenant(currentTenantId(), 0, 500);
        grid.setItems(users);
    }

    private String currentTenantId() {
        return TenantContext.require().tenantId();
    }

    private void notifyOk(String message) {
        Notification.show(message, 3000, Notification.Position.BOTTOM_START)
                .addThemeVariants(NotificationVariant.LUMO_SUCCESS);
    }

    private void notifyError(String message) {
        Notification.show(message, 5000, Notification.Position.MIDDLE)
                .addThemeVariants(NotificationVariant.LUMO_ERROR);
    }
}

package com.holonplatform.multitenant.whatsapp;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Objects;

/**
 * Descriptor for a high-level business document message (invoice, quotation, payment reminder)
 * to be sent via WhatsApp.
 *
 * <h3>Usage</h3>
 * <pre>{@code
 * // Send an invoice notification (free UTILITY template)
 * WhatsAppBusinessMessage msg = WhatsAppBusinessMessage.invoice()
 *         .to("+15551234567")
 *         .referenceNumber("INV-2024-0042")
 *         .amount(new BigDecimal("1250.00"))
 *         .currency("USD")
 *         .dueDate(LocalDate.of(2024, 6, 15))
 *         .documentUrl("https://my-app.com/invoices/INV-2024-0042.pdf")
 *         .build();
 *
 * whatsAppService.sendBusinessMessage(tenantId, msg);
 *
 * // Send a quotation
 * WhatsAppBusinessMessage quote = WhatsAppBusinessMessage.quotation()
 *         .to("+15557654321")
 *         .referenceNumber("QUOTE-0011")
 *         .amount(new BigDecimal("4800.00"))
 *         .currency("EUR")
 *         .dueDate(LocalDate.now().plusDays(30))   // valid-until date
 *         .build();
 *
 * // Send a payment reminder
 * WhatsAppBusinessMessage reminder = WhatsAppBusinessMessage.paymentReminder()
 *         .to("+15551234567")
 *         .referenceNumber("INV-2024-0042")
 *         .amount(new BigDecimal("1250.00"))
 *         .currency("USD")
 *         .dueDate(LocalDate.of(2024, 6, 15))
 *         .build();
 * }</pre>
 *
 * <p>All built-in types route through a <strong>UTILITY template (free)</strong>.
 * If an open 24-hour service window exists, the service may send a plain-text
 * summary instead, saving the template slot as well.</p>
 */
public record WhatsAppBusinessMessage(
        /** Type of business document. */
        WhatsAppBusinessMessageType messageType,
        /** Recipient phone in E.164 format (e.g. +15551234567). */
        String to,
        /** Document / reference number (invoice#, quote#, order#…). */
        String referenceNumber,
        /** Monetary amount to display. */
        BigDecimal amount,
        /** ISO-4217 currency code (USD, EUR, GBP…). */
        String currency,
        /**
         * Contextual date: due date for invoices and reminders,
         * expiry / valid-until for quotations.
         */
        LocalDate dueDate,
        /**
         * Public HTTPS URL to a PDF (or other document).
         * When set, the service sends the PDF as a WhatsApp DOCUMENT attachment
         * in addition to the template notification.
         */
        String documentUrl,
        /**
         * Override the default Meta template name.
         * If {@code null}, the service uses {@link WhatsAppBusinessMessageType#getDefaultTemplateName()}.
         */
        String templateName,
        /**
         * BCP-47 language code for the template (default: {@code en_US}).
         */
        String language,
        /**
         * Extra template parameters appended after the standard ones.
         * Keys are positional (e.g. "6", "7") or semantic labels used by custom templates.
         */
        Map<String, String> extraParams
) {

    // Compact constructor – defensive copy + guard
    public WhatsAppBusinessMessage {
        Objects.requireNonNull(messageType, "messageType");
        Objects.requireNonNull(to, "to");
        extraParams = extraParams != null ? Map.copyOf(extraParams) : Map.of();
        if (language == null || language.isBlank()) language = "en_US";
    }

    // ─── Convenience factory methods ─────────────────────────────────────────

    /** Starts building an {@link WhatsAppBusinessMessageType#INVOICE} message. */
    public static Builder invoice()         { return new Builder(WhatsAppBusinessMessageType.INVOICE); }

    /** Starts building a {@link WhatsAppBusinessMessageType#QUOTATION} message. */
    public static Builder quotation()       { return new Builder(WhatsAppBusinessMessageType.QUOTATION); }

    /** Starts building a {@link WhatsAppBusinessMessageType#PAYMENT_REMINDER} message. */
    public static Builder paymentReminder() { return new Builder(WhatsAppBusinessMessageType.PAYMENT_REMINDER); }

    /** Starts building a {@link WhatsAppBusinessMessageType#PAYMENT_OVERDUE} message. */
    public static Builder paymentOverdue()  { return new Builder(WhatsAppBusinessMessageType.PAYMENT_OVERDUE); }

    /** Starts building a {@link WhatsAppBusinessMessageType#CUSTOM} message. */
    public static Builder custom(String templateName) {
        return new Builder(WhatsAppBusinessMessageType.CUSTOM).templateName(templateName);
    }

    // ─── Builder ─────────────────────────────────────────────────────────────

    public static final class Builder {
        private final WhatsAppBusinessMessageType messageType;
        private String to;
        private String referenceNumber;
        private BigDecimal amount;
        private String currency;
        private LocalDate dueDate;
        private String documentUrl;
        private String templateName;
        private String language = "en_US";
        private final Map<String, String> extraParams = new LinkedHashMap<>();

        private Builder(WhatsAppBusinessMessageType type) {
            this.messageType = type;
        }

        /** Recipient phone number in E.164 format. */
        public Builder to(String v)               { this.to = v; return this; }

        /** Document reference number (invoice#, quote#, order#). */
        public Builder referenceNumber(String v)  { this.referenceNumber = v; return this; }

        /** Monetary amount. */
        public Builder amount(BigDecimal v)        { this.amount = v; return this; }

        /** Convenience – amount as a plain double. */
        public Builder amount(double v)            { return amount(BigDecimal.valueOf(v)); }

        /** ISO-4217 currency code (USD, EUR, GBP…). */
        public Builder currency(String v)          { this.currency = v; return this; }

        /**
         * Due date for invoices/reminders; valid-until for quotations.
         */
        public Builder dueDate(LocalDate v)        { this.dueDate = v; return this; }

        /** Public HTTPS URL to a PDF / document to attach. */
        public Builder documentUrl(String v)       { this.documentUrl = v; return this; }

        /** Override the default template name. */
        public Builder templateName(String v)      { this.templateName = v; return this; }

        /** BCP-47 language code (default: en_US). */
        public Builder language(String v)          { this.language = v; return this; }

        /** Add an extra template parameter. */
        public Builder param(String key, String value) {
            this.extraParams.put(key, value); return this;
        }

        public WhatsAppBusinessMessage build() {
            return new WhatsAppBusinessMessage(
                    messageType, to, referenceNumber, amount, currency,
                    dueDate, documentUrl, templateName, language, extraParams);
        }
    }
}

package com.holonplatform.multitenant.whatsapp;

/**
 * High-level category of a business document message sent via WhatsApp.
 *
 * <p>Every type maps to an approved <b>UTILITY template</b> (Meta category UTILITY = <em>free</em>)
 * so sending invoices, quotations and payment reminders costs nothing beyond what
 * a normal service-window reply would cost.</p>
 *
 * <p>Default template names used when no override is provided in
 * {@link WhatsAppBusinessMessage} (via the {@code templateName} field):</p>
 * <ul>
 *   <li>{@code invoice_ready}       – invoice notification</li>
 *   <li>{@code quotation_ready}     – quotation / estimate notification</li>
 *   <li>{@code payment_reminder}    – upcoming due-date reminder</li>
 *   <li>{@code payment_overdue}     – overdue-payment alert</li>
 *   <li>(caller-supplied name)      – {@link #CUSTOM}</li>
 * </ul>
 */
public enum WhatsAppBusinessMessageType {

    /**
     * An invoice is ready for payment.
     * Default template: {@code invoice_ready}
     * Default params: {{1}}=invoice#, {{2}}=amount, {{3}}=currency, {{4}}=due-date, {{5}}=download-url.
     */
    INVOICE("invoice_ready"),

    /**
     * A quotation / estimate has been prepared.
     * Default template: {@code quotation_ready}
     * Default params: {{1}}=quote#, {{2}}=amount, {{3}}=currency, {{4}}=valid-until, {{5}}=download-url.
     */
    QUOTATION("quotation_ready"),

    /**
     * A friendly payment reminder, sent before the due date.
     * Default template: {@code payment_reminder}
     * Default params: {{1}}=invoice#, {{2}}=amount, {{3}}=currency, {{4}}=due-date.
     */
    PAYMENT_REMINDER("payment_reminder"),

    /**
     * An overdue-payment alert, sent after the due date has passed.
     * Default template: {@code payment_overdue}
     * Default params: {{1}}=invoice#, {{2}}=amount, {{3}}=currency, {{4}}=due-date.
     */
    PAYMENT_OVERDUE("payment_overdue"),

    /**
     * Fully custom – caller must supply the {@code templateName} in
     * {@link WhatsAppBusinessMessage} and all required template params.
     */
    CUSTOM(null);

    private final String defaultTemplateName;

    WhatsAppBusinessMessageType(String defaultTemplateName) {
        this.defaultTemplateName = defaultTemplateName;
    }

    /**
     * Returns the default Meta template name for this type,
     * or {@code null} if this is {@link #CUSTOM}.
     */
    public String getDefaultTemplateName() {
        return defaultTemplateName;
    }
}

package com.holonplatform.multitenant.whatsapp;

import java.util.List;
import java.util.Objects;
import java.util.Optional;

/**
 * Result returned by
 * {@link TenantWhatsAppService#sendBusinessMessage(String, WhatsAppBusinessMessage)}
 * and all its convenience shortcuts.
 *
 * <p>A single business-document send may produce two WhatsApp messages:</p>
 * <ol>
 *   <li>{@link #notification()} – the text / template message carrying the
 *       document details (always present).</li>
 *   <li>{@link #attachment()} – the PDF document attachment
 *       (present only when {@link WhatsAppBusinessMessage#documentUrl()} was set).</li>
 * </ol>
 *
 * <h3>Example</h3>
 * <pre>{@code
 * WhatsAppBusinessSendResult result = whatsAppService.sendInvoice(
 *         tenantId, "+15551234567",
 *         "INV-2024-0042", new BigDecimal("1250.00"), "USD",
 *         LocalDate.of(2024, 6, 15),
 *         "https://my-app.com/invoices/INV-2024-0042.pdf");
 *
 * WhatsAppMessage notification = result.notification();
 * result.attachment().ifPresent(pdf -> log.info("PDF sent: {}", pdf.messageId()));
 * System.out.println("All messages: " + result.messages());
 * }</pre>
 */
public record WhatsAppBusinessSendResult(
        /** The template / text notification message (always present). */
        WhatsAppMessage notification,
        /**
         * The PDF document attachment message.
         * Present only when {@link WhatsAppBusinessMessage#documentUrl()} was non-null.
         */
        WhatsAppMessage attachmentMessage
) {

    public WhatsAppBusinessSendResult {
        Objects.requireNonNull(notification, "notification");
    }

    /**
     * Returns the PDF document attachment, if one was sent.
     */
    public Optional<WhatsAppMessage> attachment() {
        return Optional.ofNullable(attachmentMessage);
    }

    /**
     * Returns all messages that were sent (notification + optional attachment),
     * in send order.
     */
    public List<WhatsAppMessage> messages() {
        return attachmentMessage != null
                ? List.of(notification, attachmentMessage)
                : List.of(notification);
    }

    /**
     * Returns {@code true} if all messages were sent (or queued) without error.
     */
    public boolean isSuccess() {
        boolean notifOk = notification.status() != WhatsAppDeliveryStatus.FAILED;
        boolean attachOk = attachmentMessage == null
                || attachmentMessage.status() != WhatsAppDeliveryStatus.FAILED;
        return notifOk && attachOk;
    }

    // ── Factory ──────────────────────────────────────────────────────────────

    public static WhatsAppBusinessSendResult of(WhatsAppMessage notification) {
        return new WhatsAppBusinessSendResult(notification, null);
    }

    public static WhatsAppBusinessSendResult of(WhatsAppMessage notification,
                                                 WhatsAppMessage attachment) {
        return new WhatsAppBusinessSendResult(notification, attachment);
    }
}

package com.holonplatform.multitenant.whatsapp;

import java.time.Instant;
import java.util.Objects;

/**
 * Tracks an active WhatsApp conversation window between a tenant's business phone and a customer.
 *
 * <h3>How windows work</h3>
 * <ul>
 *   <li>A <em>service window</em> opens when the customer sends any message to the business.
 *       Within 24 hours, the business may reply with any content type <strong>free of charge</strong>.</li>
 *   <li>A <em>utility-template window</em> opens when the business sends an approved Utility template.
 *       The 24-hour clock starts from that first template message.</li>
 *   <li>If no window is open, sending a text message is not allowed (Meta API rejects it).
 *       The business must start a new conversation with a pre-approved template.</li>
 * </ul>
 *
 * <p>The {@link com.holonplatform.multitenant.whatsapp.service.ConversationWindowTracker}
 * stores one {@code WhatsAppConversation} per {@code (tenantId, customerPhone)} pair and
 * expires it automatically after {@link #expiresAt()}.</p>
 */
public record WhatsAppConversation(
        /** Composite key: {@code tenantId::customerPhone}. */
        String windowKey,
        String tenantId,
        /** Customer phone in E.164 format. */
        String customerPhone,
        WhatsAppConversationType type,
        Instant openedAt,
        /** When the 24-hour free-reply window closes. */
        Instant expiresAt,
        /** Total messages exchanged in this window. */
        int messageCount,
        /**
         * {@code true} when at least one message in this window was in a charged conversation
         * (i.e. a MARKETING or AUTHENTICATION template was used to open the conversation).
         */
        boolean charged
) {

    public WhatsAppConversation {
        Objects.requireNonNull(windowKey, "windowKey");
        Objects.requireNonNull(tenantId, "tenantId");
        Objects.requireNonNull(customerPhone, "customerPhone");
        Objects.requireNonNull(type, "type");
        Objects.requireNonNull(openedAt, "openedAt");
        Objects.requireNonNull(expiresAt, "expiresAt");
    }

    /** Returns {@code true} if the 24-hour service window is still open. */
    public boolean isOpen() {
        return Instant.now().isBefore(expiresAt);
    }

    /** Returns {@code true} if messages sent now in this window are free. */
    public boolean isFreeWindow() {
        return isOpen() && type.isFree();
    }

    public Builder toBuilder() {
        return new Builder(this);
    }

    public static Builder builder(String tenantId, String customerPhone) {
        return new Builder(tenantId, customerPhone);
    }

    // ─────────────────────────────────────────────────────────────────────────

    public static final class Builder {
        private final String windowKey;
        private final String tenantId;
        private final String customerPhone;
        private WhatsAppConversationType type = WhatsAppConversationType.SERVICE;
        private Instant openedAt = Instant.now();
        private Instant expiresAt = openedAt.plusSeconds(86_400);
        private int messageCount = 0;
        private boolean charged = false;

        private Builder(String tenantId, String customerPhone) {
            this.tenantId = Objects.requireNonNull(tenantId);
            this.customerPhone = Objects.requireNonNull(customerPhone);
            this.windowKey = tenantId + "::" + customerPhone;
        }

        private Builder(WhatsAppConversation c) {
            this.windowKey = c.windowKey();
            this.tenantId = c.tenantId();
            this.customerPhone = c.customerPhone();
            this.type = c.type();
            this.openedAt = c.openedAt();
            this.expiresAt = c.expiresAt();
            this.messageCount = c.messageCount();
            this.charged = c.charged();
        }

        public Builder type(WhatsAppConversationType v) { this.type = v; return this; }
        public Builder openedAt(Instant v) { this.openedAt = v; this.expiresAt = v.plusSeconds(86_400); return this; }
        public Builder expiresAt(Instant v) { this.expiresAt = v; return this; }
        public Builder messageCount(int v) { this.messageCount = v; return this; }
        public Builder charged(boolean v) { this.charged = v; return this; }
        public Builder incrementMessages() { this.messageCount++; return this; }

        public WhatsAppConversation build() {
            return new WhatsAppConversation(windowKey, tenantId, customerPhone,
                    type, openedAt, expiresAt, messageCount, charged);
        }
    }
}

package com.holonplatform.multitenant.whatsapp;

/**
 * WhatsApp Business conversation categories that determine billing.
 *
 * <h3>Current pricing model (Meta, effective 2024-11-01)</h3>
 * <ul>
 *   <li><b>SERVICE</b>  – user-initiated reply within 24 h window → <em>FREE (unlimited)</em></li>
 *   <li><b>UTILITY</b>  – business-initiated transactional template  → <em>FREE (unlimited)</em></li>
 *   <li><b>AUTHENTICATION</b> – OTP/verification template → <em>charged per message</em></li>
 *   <li><b>MARKETING</b>     – promotional/re-engagement template → <em>charged per conversation</em></li>
 *   <li><b>REFERRAL_CONVERSION</b> – first message from click-to-WhatsApp ad → <em>FREE first conv.</em></li>
 * </ul>
 *
 * <h3>Cost optimisation strategy</h3>
 * Always try to keep conversations in SERVICE or UTILITY category.
 * Use MARKETING only when explicitly required by the tenant's business rules and the tenant plan allows it.
 */
public enum WhatsAppConversationType {

    /**
     * User-initiated conversation (service window).
     * Any number of messages sent within the 24-hour window are <strong>free</strong>.
     * The {@link com.holonplatform.multitenant.whatsapp.service.ConversationWindowTracker}
     * tracks open windows so the service can exploit them before falling back to templates.
     */
    SERVICE,

    /**
     * Business-initiated utility template (order confirmations, delivery updates, account alerts).
     * <strong>Free</strong> since the Meta 2024 pricing simplification.
     * Prefer this over MARKETING for all transactional notifications.
     */
    UTILITY,

    /**
     * One-time password / verification code templates.
     * Charged per message; use only when OTP is genuinely required.
     */
    AUTHENTICATION,

    /**
     * Promotional, re-engagement or upsell templates.
     * Most expensive category – restricted to PROFESSIONAL and ENTERPRISE plans by default.
     */
    MARKETING,

    /**
     * Conversation started via a click-to-WhatsApp advertisement.
     * The first conversation is <strong>free</strong> regardless of template category.
     */
    REFERRAL_CONVERSION;

    /** Returns {@code true} if this conversation type results in zero additional API cost. */
    public boolean isFree() {
        return this == SERVICE || this == UTILITY || this == REFERRAL_CONVERSION;
    }

    /** Returns {@code true} if Meta charges for messages sent in this conversation. */
    public boolean isCharged() {
        return !isFree();
    }
}

package com.holonplatform.multitenant.whatsapp;

/** Lifecycle status of a single WhatsApp message. */
public enum WhatsAppDeliveryStatus {

    /** Message is queued locally, not yet submitted to the Meta Cloud API. */
    QUEUED,

    /** Submitted to Meta; awaiting delivery to the device. */
    PENDING,

    /** Accepted and dispatched by the WhatsApp server. */
    SENT,

    /** Successfully delivered to the recipient's device. */
    DELIVERED,

    /** The recipient has opened / read the message. */
    READ,

    /** Delivery permanently failed (invalid number, blocked, etc.). */
    FAILED,

    /** Message was deleted by the sender before being read. */
    DELETED
}

package com.holonplatform.multitenant.whatsapp;

import java.time.Instant;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Objects;
import java.util.UUID;

/**
 * Immutable representation of a WhatsApp message, including its delivery status
 * and whether it falls into a <em>free</em> or <em>charged</em> conversation.
 *
 * <p>Use {@link #builder()} to construct instances.</p>
 */
public record WhatsAppMessage(
        /** Local UUID assigned before the message is submitted to Meta. */
        String localId,
        /** Meta-assigned message ID (wamid.…); populated after a successful API call. */
        String messageId,
        /** Tenant that owns this message. */
        String tenantId,
        /** Recipient phone number in E.164 format (e.g. +15551234567). */
        String to,
        /** Sender phone-number-id from the Meta Business account. */
        String from,
        /** Content type. */
        WhatsAppMessageType type,
        /**
         * Conversation billing category.
         * Used by the cost optimiser to pick the cheapest sending path.
         */
        WhatsAppConversationType conversationType,
        /** Plain-text content (for TEXT type) or human-readable description. */
        String content,
        /** Template name (for TEMPLATE type). */
        String templateName,
        /** Template variable substitutions (for TEMPLATE type). */
        Map<String, String> templateParams,
        /** Current delivery status. */
        WhatsAppDeliveryStatus status,
        /** When the message was created locally. */
        Instant createdAt,
        /** When the message was submitted to Meta. */
        Instant sentAt,
        /** When Meta confirmed delivery to the device. */
        Instant deliveredAt,
        /** When the recipient marked it as read. */
        Instant readAt,
        /**
         * {@code true} when this message was sent within a free conversation window
         * (SERVICE or UTILITY category, or REFERRAL_CONVERSION first conversation).
         */
        boolean freeConversation,
        /** Meta error code when status is {@link WhatsAppDeliveryStatus#FAILED}. */
        String errorCode,
        /** Human-readable error description. */
        String errorMessage
) {

    // Compact constructor – defensive copy + guard
    public WhatsAppMessage {
        Objects.requireNonNull(localId, "localId");
        Objects.requireNonNull(tenantId, "tenantId");
        Objects.requireNonNull(to, "to");
        Objects.requireNonNull(type, "type");
        Objects.requireNonNull(status, "status");
        templateParams = templateParams != null ? Map.copyOf(templateParams) : Map.of();
    }

    /** Convenience – returns {@code true} for DELIVERED or READ. */
    public boolean isDelivered() {
        return status == WhatsAppDeliveryStatus.DELIVERED || status == WhatsAppDeliveryStatus.READ;
    }

    public boolean hasFailed() {
        return status == WhatsAppDeliveryStatus.FAILED;
    }

    public static Builder builder() {
        return new Builder();
    }

    public Builder toBuilder() {
        return new Builder(this);
    }

    // ─────────────────────────────────────────────────────────────────────────
    // Builder
    // ─────────────────────────────────────────────────────────────────────────

    public static final class Builder {
        private String localId = UUID.randomUUID().toString();
        private String messageId;
        private String tenantId;
        private String to;
        private String from;
        private WhatsAppMessageType type = WhatsAppMessageType.TEXT;
        private WhatsAppConversationType conversationType = WhatsAppConversationType.SERVICE;
        private String content;
        private String templateName;
        private final Map<String, String> templateParams = new LinkedHashMap<>();
        private WhatsAppDeliveryStatus status = WhatsAppDeliveryStatus.QUEUED;
        private Instant createdAt = Instant.now();
        private Instant sentAt;
        private Instant deliveredAt;
        private Instant readAt;
        private boolean freeConversation = true;
        private String errorCode;
        private String errorMessage;

        private Builder() {}

        private Builder(WhatsAppMessage m) {
            this.localId = m.localId();
            this.messageId = m.messageId();
            this.tenantId = m.tenantId();
            this.to = m.to();
            this.from = m.from();
            this.type = m.type();
            this.conversationType = m.conversationType();
            this.content = m.content();
            this.templateName = m.templateName();
            this.templateParams.putAll(m.templateParams());
            this.status = m.status();
            this.createdAt = m.createdAt();
            this.sentAt = m.sentAt();
            this.deliveredAt = m.deliveredAt();
            this.readAt = m.readAt();
            this.freeConversation = m.freeConversation();
            this.errorCode = m.errorCode();
            this.errorMessage = m.errorMessage();
        }

        public Builder localId(String v) { this.localId = v; return this; }
        public Builder messageId(String v) { this.messageId = v; return this; }
        public Builder tenantId(String v) { this.tenantId = v; return this; }
        public Builder to(String v) { this.to = v; return this; }
        public Builder from(String v) { this.from = v; return this; }
        public Builder type(WhatsAppMessageType v) { this.type = v; return this; }
        public Builder conversationType(WhatsAppConversationType v) { this.conversationType = v; return this; }
        public Builder content(String v) { this.content = v; return this; }
        public Builder templateName(String v) { this.templateName = v; return this; }
        public Builder templateParam(String key, String value) { this.templateParams.put(key, value); return this; }
        public Builder templateParams(Map<String, String> v) { this.templateParams.putAll(v); return this; }
        public Builder status(WhatsAppDeliveryStatus v) { this.status = v; return this; }
        public Builder createdAt(Instant v) { this.createdAt = v; return this; }
        public Builder sentAt(Instant v) { this.sentAt = v; return this; }
        public Builder deliveredAt(Instant v) { this.deliveredAt = v; return this; }
        public Builder readAt(Instant v) { this.readAt = v; return this; }
        public Builder freeConversation(boolean v) { this.freeConversation = v; return this; }
        public Builder errorCode(String v) { this.errorCode = v; return this; }
        public Builder errorMessage(String v) { this.errorMessage = v; return this; }

        public WhatsAppMessage build() {
            return new WhatsAppMessage(localId, messageId, tenantId, to, from, type,
                    conversationType, content, templateName, templateParams,
                    status, createdAt, sentAt, deliveredAt, readAt,
                    freeConversation, errorCode, errorMessage);
        }
    }
}

package com.holonplatform.multitenant.whatsapp;

/**
 * Supported WhatsApp message content types.
 * <p>
 * Cost note: every type can be sent within an open 24-hour service window at no extra charge.
 * Outside a service window you must use a pre-approved template
 * ({@link WhatsAppConversationType#UTILITY} = free,
 *  {@link WhatsAppConversationType#MARKETING} = paid).
 * </p>
 */
public enum WhatsAppMessageType {

    /** Plain-text body. */
    TEXT,

    /** Approved message template (utility, marketing, authentication). */
    TEMPLATE,

    /** JPEG/PNG image with optional caption. */
    IMAGE,

    /** PDF or other document with optional caption. */
    DOCUMENT,

    /** Audio file (.ogg OPUS preferred). */
    AUDIO,

    /** MP4 video with optional caption. */
    VIDEO,

    /** Animated sticker (.webp). */
    STICKER,

    /** Latitude/longitude location pin. */
    LOCATION,

    /** vCard contact card(s). */
    CONTACTS,

    /** Button list or product list. */
    INTERACTIVE,

    /** Emoji reaction to a specific message. */
    REACTION
}

package com.holonplatform.multitenant.whatsapp;

import java.util.List;

/**
 * Approved WhatsApp message template registered in the Meta Business Manager.
 *
 * <p>Templates are created on the Meta side and referenced by name + language when sending.
 * The {@link WhatsAppConversationType} of the template determines billing:
 * UTILITY = free, MARKETING = charged per conversation.</p>
 */
public record WhatsAppTemplate(
        String name,
        String language,
        WhatsAppConversationType category,
        /** Meta approval status: APPROVED, PENDING, REJECTED. */
        String status,
        List<TemplateComponent> components,
        String tenantId
) {

    public boolean isApproved() {
        return "APPROVED".equalsIgnoreCase(status);
    }

    public boolean isFree() {
        return category != null && category.isFree();
    }

    /**
     * A single component in the template body (HEADER, BODY, FOOTER, BUTTONS).
     *
     * @param type       component type (HEADER, BODY, FOOTER, BUTTONS)
     * @param text       raw template text with {{1}} placeholders
     * @param paramCount number of variable substitutions required
     */
    public record TemplateComponent(String type, String text, int paramCount) {}
}

package com.holonplatform.multitenant.whatsapp;

import java.time.YearMonth;
import java.util.EnumMap;
import java.util.Map;

/**
 * Monthly usage statistics for a tenant's WhatsApp channel.
 *
 * <p>The Vaadin dashboard uses this record to render a live cost breakdown,
 * helping operators understand how much of their budget is consumed by
 * {@link WhatsAppConversationType#MARKETING} (charged) vs free categories.</p>
 *
 * @param tenantId           tenant identifier
 * @param period             billing month
 * @param totalMessages      all outbound messages (queued + sent + delivered)
 * @param freeMessages       messages sent in free conversation windows
 * @param chargedMessages    messages that triggered a billing entry
 * @param byConversationType message counts grouped by conversation type
 * @param openWindows        number of currently active 24-hour service windows
 * @param estimatedCostUsd   rough cost estimate (USD) based on Meta's published rates
 */
public record WhatsAppUsageStats(
        String tenantId,
        YearMonth period,
        long totalMessages,
        long freeMessages,
        long chargedMessages,
        Map<WhatsAppConversationType, Long> byConversationType,
        int openWindows,
        double estimatedCostUsd
) {

    /** Returns the percentage of messages that were free (0-100). */
    public double freePercentage() {
        if (totalMessages == 0) return 100.0;
        return (double) freeMessages / totalMessages * 100.0;
    }

    public static Builder builder(String tenantId, YearMonth period) {
        return new Builder(tenantId, period);
    }

    public static final class Builder {
        private final String tenantId;
        private final YearMonth period;
        private long totalMessages;
        private long freeMessages;
        private long chargedMessages;
        private final Map<WhatsAppConversationType, Long> byType = new EnumMap<>(WhatsAppConversationType.class);
        private int openWindows;
        private double estimatedCostUsd;

        private Builder(String tenantId, YearMonth period) {
            this.tenantId = tenantId;
            this.period = period;
        }

        public Builder totalMessages(long v) { this.totalMessages = v; return this; }
        public Builder freeMessages(long v) { this.freeMessages = v; return this; }
        public Builder chargedMessages(long v) { this.chargedMessages = v; return this; }
        public Builder count(WhatsAppConversationType type, long count) { this.byType.put(type, count); return this; }
        public Builder openWindows(int v) { this.openWindows = v; return this; }
        public Builder estimatedCostUsd(double v) { this.estimatedCostUsd = v; return this; }

        public WhatsAppUsageStats build() {
            return new WhatsAppUsageStats(tenantId, period, totalMessages, freeMessages,
                    chargedMessages, Map.copyOf(byType), openWindows, estimatedCostUsd);
        }
    }
}

package com.holonplatform.multitenant.whatsapp.client;

import com.fasterxml.jackson.annotation.JsonIgnoreProperties;
import com.fasterxml.jackson.annotation.JsonProperty;
import com.holonplatform.multitenant.whatsapp.WhatsAppConversationType;
import com.holonplatform.multitenant.whatsapp.WhatsAppTemplate;
import com.holonplatform.multitenant.whatsapp.exception.WhatsAppException;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.MediaType;
import org.springframework.web.client.RestClient;
import org.springframework.web.client.RestClientException;

import java.util.Collections;
import java.util.List;
import java.util.Map;

/**
 * Thin HTTP wrapper around the <b>Meta WhatsApp Business Cloud API v21.0</b>.
 *
 * <p>Instances are created per-tenant (or shared in SHARED mode) by
 * {@link com.holonplatform.multitenant.whatsapp.config.TenantWhatsAppAutoConfiguration}.</p>
 *
 * <h3>API endpoints used</h3>
 * <ul>
 *   <li>{@code POST /v21.0/{phone-number-id}/messages} – send any message type</li>
 *   <li>{@code GET  /v21.0/{waba-id}/message_templates} – list approved templates</li>
 * </ul>
 *
 * <h3>Auth</h3>
 * Uses a <em>System User Access Token</em> passed as {@code Authorization: Bearer <token>}.
 * Tokens never expire if granted to a System User with "standard" token type.
 */
public class WhatsAppCloudApiClient {

    private static final Logger log = LoggerFactory.getLogger(WhatsAppCloudApiClient.class);
    private static final String BASE_URL = "https://graph.facebook.com/v21.0";

    private final String phoneNumberId;
    private final String wabaId;
    private final RestClient restClient;

    public WhatsAppCloudApiClient(String phoneNumberId, String wabaId, String accessToken) {
        this.phoneNumberId = phoneNumberId;
        this.wabaId = wabaId;
        this.restClient = RestClient.builder()
                .baseUrl(BASE_URL)
                .defaultHeader("Authorization", "Bearer " + accessToken)
                .defaultHeader("Content-Type", MediaType.APPLICATION_JSON_VALUE)
                .build();
    }

    // ─── Send text ────────────────────────────────────────────────────────────

    /**
     * Sends a plain-text message.  Only valid when a 24-hour service window is open.
     *
     * @return Meta-assigned message ID (wamid.…)
     */
    public String sendText(String to, String text) {
        Map<String, Object> body = Map.of(
                "messaging_product", "whatsapp",
                "recipient_type", "individual",
                "to", to,
                "type", "text",
                "text", Map.of("preview_url", false, "body", text)
        );
        return callMessages(body);
    }

    // ─── Send template ────────────────────────────────────────────────────────

    /**
     * Sends an approved message template with ordered parameter substitutions.
     *
     * @param to           recipient E.164 phone
     * @param templateName template name in Business Manager
     * @param language     BCP-47 code, e.g. {@code "en_US"}
     * @param bodyParams   ordered body component parameters ({{1}}, {{2}}, …)
     * @return Meta-assigned message ID
     */
    public String sendTemplate(String to, String templateName, String language,
                               List<String> bodyParams) {
        List<Map<String, Object>> paramObjects = bodyParams.stream()
                .map(v -> Map.<String, Object>of("type", "text", "text", v))
                .toList();

        Map<String, Object> templateObj = Map.of(
                "name", templateName,
                "language", Map.of("code", language),
                "components", Collections.singletonList(Map.of(
                        "type", "body",
                        "parameters", paramObjects
                ))
        );

        Map<String, Object> body = Map.of(
                "messaging_product", "whatsapp",
                "to", to,
                "type", "template",
                "template", templateObj
        );
        return callMessages(body);
    }

    // ─── Send media ───────────────────────────────────────────────────────────

    /**
     * Sends an image, document, audio or video message.
     *
     * @param to        recipient E.164 phone
     * @param mediaType WhatsApp media type string ("image", "document", "audio", "video")
     * @param mediaUrl  public HTTPS URL or a Meta media-id
     * @param caption   optional caption for image/document/video
     * @return Meta-assigned message ID
     */
    public String sendMedia(String to, String mediaType, String mediaUrl, String caption) {
        Map<String, Object> mediaObj = caption != null && !caption.isBlank()
                ? Map.of("link", mediaUrl, "caption", caption)
                : Map.of("link", mediaUrl);

        Map<String, Object> body = Map.of(
                "messaging_product", "whatsapp",
                "to", to,
                "type", mediaType,
                mediaType, mediaObj
        );
        return callMessages(body);
    }

    // ─── List templates ───────────────────────────────────────────────────────

    /** Fetches approved templates from the Meta Business account. */
    public List<WhatsAppTemplate> fetchTemplates() {
        try {
            TemplateListResponse response = restClient.get()
                    .uri("/{wabaId}/message_templates?fields=name,language,category,status,components",
                            wabaId)
                    .retrieve()
                    .body(TemplateListResponse.class);

            if (response == null || response.data() == null) return List.of();

            return response.data().stream().map(t -> {
                WhatsAppConversationType category = switch (t.category() == null ? "" : t.category().toUpperCase()) {
                    case "UTILITY" -> WhatsAppConversationType.UTILITY;
                    case "AUTHENTICATION" -> WhatsAppConversationType.AUTHENTICATION;
                    case "MARKETING" -> WhatsAppConversationType.MARKETING;
                    default -> WhatsAppConversationType.UTILITY;
                };
                return new WhatsAppTemplate(t.name(), t.language(), category, t.status(),
                        List.of(), null);
            }).toList();

        } catch (RestClientException e) {
            log.warn("Failed to fetch WhatsApp templates for WABA {}: {}", wabaId, e.getMessage());
            return List.of();
        }
    }

    // ─── Internal ───────────────────────────���─────────────────────────────────

    private String callMessages(Map<String, Object> body) {
        try {
            SendMessageResponse resp = restClient.post()
                    .uri("/{phoneNumberId}/messages", phoneNumberId)
                    .body(body)
                    .retrieve()
                    .body(SendMessageResponse.class);

            if (resp == null || resp.messages() == null || resp.messages().isEmpty()) {
                throw new WhatsAppException("Empty response from Meta Cloud API");
            }
            String messageId = resp.messages().getFirst().id();
            log.debug("Message sent via Meta API: {}", messageId);
            return messageId;

        } catch (RestClientException e) {
            throw new WhatsAppException("Meta Cloud API call failed: " + e.getMessage(), e);
        }
    }

    // ─── Response DTOs ────────────────────────────────────────────────────────

    @JsonIgnoreProperties(ignoreUnknown = true)
    public record SendMessageResponse(
            @JsonProperty("messages") List<MessageRef> messages) {}

    @JsonIgnoreProperties(ignoreUnknown = true)
    public record MessageRef(@JsonProperty("id") String id) {}

    @JsonIgnoreProperties(ignoreUnknown = true)
    public record TemplateListResponse(
            @JsonProperty("data") List<TemplateDto> data) {}

    @JsonIgnoreProperties(ignoreUnknown = true)
    public record TemplateDto(
            @JsonProperty("name") String name,
            @JsonProperty("language") String language,
            @JsonProperty("category") String category,
            @JsonProperty("status") String status) {}
}

package com.holonplatform.multitenant.whatsapp.config;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.holonplatform.multitenant.whatsapp.TenantWhatsAppService;
import com.holonplatform.multitenant.whatsapp.service.ConversationWindowTracker;
import com.holonplatform.multitenant.whatsapp.service.InMemoryTenantWhatsAppService;
import com.holonplatform.multitenant.whatsapp.webhook.WhatsAppWebhookController;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.boot.autoconfigure.AutoConfiguration;
import org.springframework.boot.autoconfigure.condition.ConditionalOnMissingBean;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.boot.context.properties.EnableConfigurationProperties;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.ComponentScan;
import org.springframework.scheduling.annotation.EnableScheduling;

/**
 * Spring Boot auto-configuration for the WhatsApp integration module.
 *
 * <h3>What this configures</h3>
 * <ul>
 *   <li>{@link ConversationWindowTracker} – in-memory 24-hour window tracker</li>
 *   <li>{@link InMemoryTenantWhatsAppService} – default service (replace with your own bean)</li>
 *   <li>{@link WhatsAppWebhookController} – REST endpoint for Meta webhooks</li>
 * </ul>
 *
 * <h3>Replacing the default implementation</h3>
 * <pre>
 * {@code @Service}
 * public class MyWhatsAppService implements TenantWhatsAppService { ... }
 * </pre>
 * The auto-configuration uses {@code @ConditionalOnMissingBean} so your custom bean takes precedence.
 */
@AutoConfiguration
@ConditionalOnProperty(name = "holon.tenant.whatsapp.enabled", havingValue = "true", matchIfMissing = true)
@EnableConfigurationProperties(TenantWhatsAppProperties.class)
// Only scan the Vaadin UI package – Vaadin's route scanner needs to discover the views.
// The service and webhook classes are created exclusively by @Bean methods below,
// so they must NOT be component-scanned (avoids double-registration and ensures
// ObjectMapper is available from JacksonAutoConfiguration before the service is built).
@ComponentScan(basePackages = {
        "com.holonplatform.multitenant.whatsapp.ui"
})
@EnableScheduling
public class TenantWhatsAppAutoConfiguration {

    private static final Logger log = LoggerFactory.getLogger(TenantWhatsAppAutoConfiguration.class);

    @Bean
    @ConditionalOnMissingBean
    public ConversationWindowTracker conversationWindowTracker() {
        log.debug("Registering WhatsApp ConversationWindowTracker");
        return new ConversationWindowTracker();
    }

    @Bean
    @ConditionalOnMissingBean(TenantWhatsAppService.class)
    public TenantWhatsAppService tenantWhatsAppService(
            ConversationWindowTracker tracker,
            TenantWhatsAppProperties properties,
            ObjectProvider<ObjectMapper> objectMapperProvider) {
        log.info("Registering WhatsApp service (InMemoryTenantWhatsAppService)");
        // Use the application's ObjectMapper if available, otherwise fall back to a default one.
        ObjectMapper objectMapper = objectMapperProvider.getIfAvailable(ObjectMapper::new);
        return new InMemoryTenantWhatsAppService(tracker, properties, objectMapper);
    }

    @Bean
    @ConditionalOnMissingBean
    @ConditionalOnProperty(name = "holon.tenant.whatsapp.webhook.enabled",
            havingValue = "true", matchIfMissing = true)
    public WhatsAppWebhookController whatsAppWebhookController(
            TenantWhatsAppService service,
            TenantWhatsAppProperties properties) {
        log.debug("Registering WhatsApp webhook controller at /webhook/whatsapp");
        return new WhatsAppWebhookController(service, properties);
    }
}

package com.holonplatform.multitenant.whatsapp.exception;

/** Base exception for all WhatsApp integration errors. */
public class WhatsAppException extends RuntimeException {

    private static final long serialVersionUID = 1L;

    public WhatsAppException(String message) {
        super(message);
    }

    public WhatsAppException(String message, Throwable cause) {
        super(message, cause);
    }
}

package com.holonplatform.multitenant.whatsapp.exception;

/**
 * Thrown when the WhatsApp integration has not been configured for a tenant
 * (missing phone-number-id, access token, or WABA credentials).
 */
public class WhatsAppNotConfiguredException extends WhatsAppException {

    private static final long serialVersionUID = 1L;

    public WhatsAppNotConfiguredException(String tenantId) {
        super("WhatsApp is not configured for tenant '%s'. "
                + "Set holon.tenant.whatsapp.shared.* or provide a TenantWhatsAppCredentialsProvider bean."
                        .formatted(tenantId));
    }
}

package com.holonplatform.multitenant.whatsapp.exception;

/**
 * Thrown when a tenant has exhausted its configured WhatsApp message quota for the current month.
 * The quota is enforced per {@link com.holonplatform.multitenant.TenantPlan}:
 * FREE → 50 marketing messages/month, STARTER → 200, PROFESSIONAL → 2 000, ENTERPRISE → unlimited.
 */
public class WhatsAppQuotaExceededException extends WhatsAppException {

    private static final long serialVersionUID = 1L;

    private final String tenantId;
    private final int limit;
    private final int current;

    public WhatsAppQuotaExceededException(String tenantId, int limit, int current) {
        super("WhatsApp marketing quota exceeded for tenant '%s': limit=%d, current=%d"
                .formatted(tenantId, limit, current));
        this.tenantId = tenantId;
        this.limit = limit;
        this.current = current;
    }

    public String getTenantId() { return tenantId; }
    public int getLimit()       { return limit; }
    public int getCurrent()     { return current; }
}

package com.holonplatform.multitenant.whatsapp.service;

import com.holonplatform.multitenant.whatsapp.WhatsAppConversation;
import com.holonplatform.multitenant.whatsapp.WhatsAppConversationType;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.scheduling.annotation.Scheduled;

import java.time.Instant;
import java.util.Collection;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Tracks active 24-hour WhatsApp conversation windows per {@code (tenantId, customerPhone)}.
 *
 * <h3>Why this component is the most important cost-saving mechanism</h3>
 * <p>
 * WhatsApp charges for business-initiated conversations only when the business
 * has to <em>start</em> a new conversation (typically by sending a template).
 * {@link WhatsAppConversationType#MARKETING} templates cost the most.
 * However, when a <em>customer sends a message first</em>, a free 24-hour
 * <em>service window</em> opens.  Inside that window the business can reply
 * with any content (text, images, documents) at <strong>zero extra cost</strong>.
 * </p>
 *
 * <h3>Usage in the sending pipeline</h3>
 * <pre>{@code
 * if (tracker.hasOpenFreeWindow(tenantId, to)) {
 *     // send a plain TEXT message – completely free
 * } else {
 *     // no open window → must start a new conversation with a template
 *     // prefer UTILITY template (free) over MARKETING (charged)
 * }
 * }</pre>
 *
 * <p>Windows are stored in memory (default) and cleaned up by a scheduled task.
 * Production deployments can replace this bean with a Redis-backed implementation
 * for distributed environments.</p>
 */
public class ConversationWindowTracker {

    private static final Logger log = LoggerFactory.getLogger(ConversationWindowTracker.class);

    /** tenantId → customerPhone → active window */
    private final ConcurrentHashMap<String, ConcurrentHashMap<String, WhatsAppConversation>> windows =
            new ConcurrentHashMap<>();

    // ─── Public API ───────────────────────────────────────────────────────────

    /**
     * Returns {@code true} if a free 24-hour window is open for the customer.
     * The service layer calls this before every outbound message to decide whether
     * a free plain-text reply is possible.
     */
    public boolean hasOpenFreeWindow(String tenantId, String customerPhone) {
        return getWindow(tenantId, customerPhone)
                .map(WhatsAppConversation::isFreeWindow)
                .orElse(false);
    }

    /**
     * Returns the current conversation window, regardless of whether it is free.
     */
    public Optional<WhatsAppConversation> getWindow(String tenantId, String customerPhone) {
        WhatsAppConversation w = tenantWindows(tenantId).get(normalise(customerPhone));
        if (w == null) return Optional.empty();
        if (!w.isOpen()) {
            // lazily evict expired window
            tenantWindows(tenantId).remove(normalise(customerPhone));
            return Optional.empty();
        }
        return Optional.of(w);
    }

    /**
     * Called when an <em>inbound</em> message arrives from a customer.
     * Opens (or refreshes) a 24-hour SERVICE window – the cheapest possible window.
     */
    public WhatsAppConversation registerInboundMessage(String tenantId, String customerPhone) {
        String key = normalise(customerPhone);
        WhatsAppConversation existing = tenantWindows(tenantId).get(key);

        Instant now = Instant.now();
        WhatsAppConversation updated;

        if (existing != null && existing.isOpen()) {
            // refresh window + increment message count
            updated = existing.toBuilder()
                    .expiresAt(now.plusSeconds(86_400))
                    .incrementMessages()
                    .build();
        } else {
            // open a brand-new free service window
            updated = WhatsAppConversation.builder(tenantId, customerPhone)
                    .type(WhatsAppConversationType.SERVICE)
                    .openedAt(now)
                    .expiresAt(now.plusSeconds(86_400))
                    .messageCount(1)
                    .charged(false)
                    .build();
        }

        tenantWindows(tenantId).put(key, updated);
        log.debug("Service window opened/refreshed for {}/{} – expires {}", tenantId, customerPhone, updated.expiresAt());
        return updated;
    }

    /**
     * Called when the business sends a template message.
     * Records whether the conversation started by this template is charged.
     *
     * @param type  category of the template being sent
     */
    public WhatsAppConversation registerOutboundTemplate(String tenantId, String customerPhone,
                                                          WhatsAppConversationType type) {
        String key = normalise(customerPhone);
        Instant now = Instant.now();

        WhatsAppConversation conv = WhatsAppConversation.builder(tenantId, customerPhone)
                .type(type)
                .openedAt(now)
                .expiresAt(now.plusSeconds(86_400))
                .messageCount(1)
                .charged(type.isCharged())
                .build();

        tenantWindows(tenantId).put(key, conv);
        log.debug("Template window ({}) opened for {}/{}", type, tenantId, customerPhone);
        return conv;
    }

    /**
     * Records an outbound message inside an already-open window.
     */
    public void recordOutboundMessage(String tenantId, String customerPhone) {
        String key = normalise(customerPhone);
        tenantWindows(tenantId).computeIfPresent(key,
                (k, w) -> w.toBuilder().incrementMessages().build());
    }

    /**
     * Returns all currently open windows for a tenant (used by the Vaadin dashboard).
     */
    public Collection<WhatsAppConversation> openWindowsForTenant(String tenantId) {
        return tenantWindows(tenantId).values().stream()
                .filter(WhatsAppConversation::isOpen)
                .toList();
    }

    /** Returns the number of currently open free windows across all tenants (observability). */
    public long totalOpenWindows() {
        return windows.values().stream()
                .flatMap(m -> m.values().stream())
                .filter(WhatsAppConversation::isOpen)
                .count();
    }

    // ─── Background cleanup ───────────────────────────────────────────────────

    /** Purges expired windows every 10 minutes to prevent memory growth. */
    @Scheduled(fixedDelay = 600_000)
    public void evictExpiredWindows() {
        int removed = 0;
        for (Map.Entry<String, ConcurrentHashMap<String, WhatsAppConversation>> tenant : windows.entrySet()) {
            List<String> expired = tenant.getValue().entrySet().stream()
                    .filter(e -> !e.getValue().isOpen())
                    .map(Map.Entry::getKey)
                    .toList();
            expired.forEach(tenant.getValue()::remove);
            removed += expired.size();
        }
        if (removed > 0) log.debug("Evicted {} expired WhatsApp conversation windows", removed);
    }

    // ─── Helpers ──────────────────────────────────────────────────────────────

    private ConcurrentHashMap<String, WhatsAppConversation> tenantWindows(String tenantId) {
        return windows.computeIfAbsent(tenantId, k -> new ConcurrentHashMap<>());
    }

    /** Normalises phone to E.164 without spaces or dashes (best-effort). */
    private static String normalise(String phone) {
        if (phone == null) return "";
        String n = phone.replaceAll("[\\s\\-()]", "");
        return n.startsWith("+") ? n : "+" + n;
    }
}

package com.holonplatform.multitenant.whatsapp.ui;

import com.vaadin.flow.component.applayout.AppLayout;
import com.vaadin.flow.component.applayout.DrawerToggle;
import com.vaadin.flow.component.html.H2;
import com.vaadin.flow.component.html.Span;
import com.vaadin.flow.component.icon.VaadinIcon;
import com.vaadin.flow.component.sidenav.SideNav;
import com.vaadin.flow.component.sidenav.SideNavItem;
import com.vaadin.flow.router.Layout;
import com.vaadin.flow.theme.lumo.LumoUtility;
import com.holonplatform.multitenant.whatsapp.ui.views.WhatsAppDashboardView;
import com.holonplatform.multitenant.whatsapp.ui.views.WhatsAppConversationsView;
import com.holonplatform.multitenant.whatsapp.ui.views.WhatsAppTemplatesView;
import com.holonplatform.multitenant.whatsapp.ui.views.WhatsAppSettingsView;

/**
 * App shell layout for the WhatsApp management section at {@code /whatsapp/**}.
 *
 * <p>Access this section at {@code http://localhost:8080/whatsapp}.</p>
 */
@Layout("/whatsapp")
public class WhatsAppManageLayout extends AppLayout {

    public WhatsAppManageLayout() {
        setPrimarySection(Section.DRAWER);
        addToNavbar(true, new DrawerToggle());

        H2 title = new H2(" WhatsApp");
        title.addClassNames(LumoUtility.FontSize.LARGE, LumoUtility.Margin.NONE);
        addToNavbar(title);

        SideNav nav = new SideNav();

        SideNavItem dashboard = new SideNavItem("Dashboard",
                WhatsAppDashboardView.class, VaadinIcon.DASHBOARD.create());
        SideNavItem conversations = new SideNavItem("Conversations",
                WhatsAppConversationsView.class, VaadinIcon.COMMENTS.create());
        SideNavItem templates = new SideNavItem("Templates",
                WhatsAppTemplatesView.class, VaadinIcon.FILE_TEXT.create());
        SideNavItem settings = new SideNavItem("Settings",
                WhatsAppSettingsView.class, VaadinIcon.COG.create());

        nav.addItem(dashboard, conversations, templates, settings);

        Span footer = new Span("WhatsApp Business Cloud API");
        footer.addClassNames(LumoUtility.FontSize.XSMALL, LumoUtility.TextColor.SECONDARY,
                LumoUtility.Padding.SMALL);

        addToDrawer(nav, footer);
    }
}

package com.holonplatform.multitenant.whatsapp.ui.views;

import com.holonplatform.multitenant.TenantContext;
import com.holonplatform.multitenant.whatsapp.TenantWhatsAppService;
import com.holonplatform.multitenant.whatsapp.WhatsAppConversation;
import com.holonplatform.multitenant.whatsapp.WhatsAppMessage;
import com.holonplatform.multitenant.whatsapp.ui.WhatsAppManageLayout;
import com.vaadin.flow.component.AttachEvent;
import com.vaadin.flow.component.button.Button;
import com.vaadin.flow.component.button.ButtonVariant;
import com.vaadin.flow.component.grid.Grid;
import com.vaadin.flow.component.html.Div;
import com.vaadin.flow.component.html.H3;
import com.vaadin.flow.component.html.Paragraph;
import com.vaadin.flow.component.orderedlayout.HorizontalLayout;
import com.vaadin.flow.component.orderedlayout.VerticalLayout;
import com.vaadin.flow.component.textfield.TextField;
import com.vaadin.flow.router.PageTitle;
import com.vaadin.flow.router.Route;
import com.vaadin.flow.theme.lumo.LumoUtility;

import java.time.ZoneOffset;
import java.time.format.DateTimeFormatter;

/**
 * Shows all active 24-hour conversation windows and per-phone message history.
 *
 * <h3>Lazy loading</h3>
 * The message-history grid uses {@code setItems(query -&gt; …)} in
 * unknown-item-count mode, delegating to
 * {@link TenantWhatsAppService#listMessages(String, int, int)}.
 * The window grid is populated eagerly (active windows are a small set).
 * All data loading starts in {@link #onAttach(AttachEvent)}.
 */
@Route(value = "whatsapp/conversations", layout = WhatsAppManageLayout.class)
@PageTitle("WhatsApp Conversations")
public class WhatsAppConversationsView extends VerticalLayout {

    private static final DateTimeFormatter FMT =
            DateTimeFormatter.ofPattern("dd MMM HH:mm z").withZone(ZoneOffset.UTC);

    private final TenantWhatsAppService service;

    private final Grid<WhatsAppConversation> windowGrid  = new Grid<>(WhatsAppConversation.class, false);
    private final Grid<WhatsAppMessage>      historyGrid = new Grid<>(WhatsAppMessage.class, false);
    private final TextField                  phoneSearch = new TextField();

    /** Phone currently shown in the history grid; used by the lazy data callback. */
    private String activePhone = null;

    public WhatsAppConversationsView(TenantWhatsAppService service) {
        this.service = service;
        setSizeFull();
        setPadding(true);
        setSpacing(true);
        // Constructor: build structure only – no service calls
        add(buildWindowSection(), buildHistorySection());
    }

    @Override
    protected void onAttach(AttachEvent event) {
        super.onAttach(event);
        refreshWindows();
    }

    // ── Active windows ────────────────────────────────────────────────────────

    private Div buildWindowSection() {
        windowGrid.addColumn(WhatsAppConversation::customerPhone)
                .setHeader("Customer Phone").setAutoWidth(true);
        windowGrid.addColumn(c -> c.type().name())
                .setHeader("Type").setWidth("120px");
        windowGrid.addColumn(c -> c.isFreeWindow() ? " Open / Free" : " Expired")
                .setHeader("Window Status").setWidth("160px");
        windowGrid.addColumn(c -> FMT.format(c.expiresAt()))
                .setHeader("Expires (UTC)").setWidth("180px");
        windowGrid.addColumn(c -> c.charged() ? " Charged" : "✅ Free")
                .setHeader("Cost").setWidth("110px");
        windowGrid.addColumn(WhatsAppConversation::messageCount)
                .setHeader("Messages").setWidth("100px");

        // Row click → load history for that phone via lazy grid reset
        windowGrid.asSingleSelect().addValueChangeListener(e -> {
            WhatsAppConversation c = e.getValue();
            if (c != null) showHistoryFor(c.customerPhone());
        });

        windowGrid.setHeight("280px");
        windowGrid.setWidthFull();

        Paragraph hint = new Paragraph(
                " Rows with  have an open 24-h service window — replies are free. "
                        + "Click a row to inspect its message history.");
        hint.addClassNames(LumoUtility.FontSize.SMALL, LumoUtility.TextColor.SECONDARY,
                LumoUtility.Margin.NONE);

        Button refreshBtn = new Button("↻ Refresh", e -> refreshWindows());
        refreshBtn.addThemeVariants(ButtonVariant.LUMO_TERTIARY);

        HorizontalLayout header = new HorizontalLayout(new H3(" Active Service Windows"), refreshBtn);
        header.setAlignItems(Alignment.BASELINE);
        header.setJustifyContentMode(JustifyContentMode.BETWEEN);
        header.setWidthFull();

        Div card = new Div(header, hint, windowGrid);
        card.addClassNames(LumoUtility.Padding.MEDIUM, LumoUtility.BorderRadius.MEDIUM,
                LumoUtility.Background.CONTRAST_5);
        card.setWidthFull();
        return card;
    }

    // ── Message history (lazy) ────────────────────────────────────────────────

    private Div buildHistorySection() {
        phoneSearch.setPlaceholder("Search by phone (+15551234567)");
        phoneSearch.setWidth("280px");
        Button searchBtn = new Button("Search", e -> showHistoryFor(phoneSearch.getValue()));
        searchBtn.addThemeVariants(ButtonVariant.LUMO_PRIMARY);

        historyGrid.addColumn(m -> FMT.format(m.createdAt()))
                .setHeader("Time (UTC)").setWidth("180px");
        historyGrid.addColumn(WhatsAppMessage::to)
                .setHeader("To").setAutoWidth(true);
        historyGrid.addColumn(m -> m.type().name())
                .setHeader("Type").setWidth("100px");
        historyGrid.addColumn(m -> m.freeConversation() ? "✅ Free" : " Charged")
                .setHeader("Cost").setWidth("110px");
        historyGrid.addColumn(m -> m.status().name())
                .setHeader("Status").setWidth("110px");
        historyGrid.addColumn(m -> truncate(m.content(), 80))
                .setHeader("Content").setFlexGrow(1);

        // ── Lazy provider — reads activePhone at fetch time ───────────────────
        historyGrid.setItems(query -> {
            String tenantId = TenantContext.currentTenantId().orElse("demo");
            if (activePhone == null || activePhone.isBlank()) {
                // No phone selected: stream all messages lazily
                return service.listMessages(tenantId, query.getOffset(), query.getLimit()).stream();
            }
            // Phone-filtered: listMessagesByPhone is small so offset/limit respected manually
            var all = service.listMessagesByPhone(tenantId, activePhone);
            int from = Math.min(query.getOffset(), all.size());
            int to   = Math.min(query.getOffset() + query.getLimit(), all.size());
            return all.subList(from, to).stream();
        });

        historyGrid.setHeight("300px");
        historyGrid.setWidthFull();

        HorizontalLayout searchRow = new HorizontalLayout(phoneSearch, searchBtn);
        searchRow.setAlignItems(Alignment.END);

        Div card = new Div(new H3(" Message History (lazy)"), searchRow, historyGrid);
        card.addClassNames(LumoUtility.Padding.MEDIUM, LumoUtility.BorderRadius.MEDIUM,
                LumoUtility.Background.CONTRAST_5);
        card.setWidthFull();
        return card;
    }

    // ── Data refresh ──────────────────────────────────────────────────────────

    private void refreshWindows() {
        String tenantId = TenantContext.currentTenantId().orElse("demo");
        // Collect distinct customer phones from recent messages and look up their windows.
        // Each phone appears at most once; only open windows are shown.
        var windows = service.listMessages(tenantId, 0, 200).stream()
                .map(WhatsAppMessage::to)
                .distinct()
                .map(phone -> service.getConversationWindow(tenantId, phone))
                .filter(java.util.Optional::isPresent)
                .map(java.util.Optional::get)
                .filter(WhatsAppConversation::isOpen)
                .toList();
        windowGrid.setItems(windows);
    }

    private void showHistoryFor(String phone) {
        if (phone == null || phone.isBlank()) return;
        activePhone = phone;
        phoneSearch.setValue(phone);
        // Tell the lazy provider to re-fetch from offset 0
        historyGrid.getDataCommunicator().reset();
    }

    private static String truncate(String s, int max) {
        if (s == null) return "";
        return s.length() > max ? s.substring(0, max) + "…" : s;
    }
}

package com.holonplatform.multitenant.whatsapp.ui.views;

import com.holonplatform.multitenant.TenantContext;
import com.holonplatform.multitenant.whatsapp.TenantWhatsAppService;
import com.holonplatform.multitenant.whatsapp.WhatsAppMessage;
import com.holonplatform.multitenant.whatsapp.WhatsAppUsageStats;
import com.holonplatform.multitenant.whatsapp.ui.WhatsAppManageLayout;
import com.vaadin.flow.component.AttachEvent;
import com.vaadin.flow.component.button.Button;
import com.vaadin.flow.component.button.ButtonVariant;
import com.vaadin.flow.component.grid.Grid;
import com.vaadin.flow.component.html.Div;
import com.vaadin.flow.component.html.H2;
import com.vaadin.flow.component.html.H3;
import com.vaadin.flow.component.html.Paragraph;
import com.vaadin.flow.component.html.Span;
import com.vaadin.flow.component.notification.Notification;
import com.vaadin.flow.component.notification.NotificationVariant;
import com.vaadin.flow.component.orderedlayout.FlexLayout;
import com.vaadin.flow.component.orderedlayout.HorizontalLayout;
import com.vaadin.flow.component.orderedlayout.VerticalLayout;
import com.vaadin.flow.component.progressbar.ProgressBar;
import com.vaadin.flow.component.textfield.TextField;
import com.vaadin.flow.router.PageTitle;
import com.vaadin.flow.router.Route;
import com.vaadin.flow.theme.lumo.LumoUtility;

import java.time.YearMonth;
import java.time.format.DateTimeFormatter;

/**
 * WhatsApp cost-optimisation and usage dashboard.
 *
 * <h3>Lazy loading</h3>
 * The recent-messages {@link Grid} uses Vaadin's {@code setItems(query -&gt; …)}
 * callback (unknown-item-count mode), fetching one page at a time via
 * {@link TenantWhatsAppService#listMessages(String, int, int)}.
 * No service calls are made in the constructor; data loading starts in
 * {@link #onAttach(AttachEvent)} after the component is attached to the UI.
 *
 * <h3>Cost insight panels</h3>
 * <ul>
 *   <li>Free-traffic ratio progress bar</li>
 *   <li>Open service windows (free 24-h reply windows)</li>
 *   <li>Estimated cost in USD</li>
 *   <li>Quick-send with live free/charged classification</li>
 * </ul>
 */
@Route(value = "whatsapp", layout = WhatsAppManageLayout.class)
@PageTitle("WhatsApp Dashboard")
public class WhatsAppDashboardView extends VerticalLayout {

    private final TenantWhatsAppService service;

    // ── Stat card spans ───────────────────────────────────────────────────────
    private final Span totalSpan   = new Span("–");
    private final Span freeSpan    = new Span("–");
    private final Span chargedSpan = new Span("–");
    private final Span windowsSpan = new Span("–");
    private final Span costSpan    = new Span("$–");

    /** Free-traffic ratio bar.  Range: 0–100 (percentage). */
    private final ProgressBar freeBar = new ProgressBar(0, 100);

    // ── Quick-send fields ─────────────────────────────────────────────────────
    private final TextField toField   = new TextField("Recipient (E.164)");
    private final TextField textField = new TextField("Message");

    // ── Lazy message grid ─────────────────────────────────────────────────────
    private final Grid<WhatsAppMessage> recentGrid = new Grid<>(WhatsAppMessage.class, false);

    public WhatsAppDashboardView(TenantWhatsAppService service) {
        this.service = service;
        setSizeFull();
        setPadding(true);
        setSpacing(true);
        // Constructor: build UI structure only – no service calls here
        add(buildHeader(), buildStatCards(), buildQuickSend(), buildRecentMessages());
    }

    // ── Lazy init ─────────────────────────────────────────────────────────────

    @Override
    protected void onAttach(AttachEvent event) {
        super.onAttach(event);
        refreshStats();
        // Reset the lazy data-communicator so the first page is fetched fresh
        // each time this view is (re-)opened.
        recentGrid.getDataCommunicator().reset();
    }

    // ── Header ────────────────────────────────────────────────────────────────

    private HorizontalLayout buildHeader() {
        H2 heading = new H2(" WhatsApp Dashboard – "
                + YearMonth.now().format(DateTimeFormatter.ofPattern("MMMM yyyy")));
        heading.addClassNames(LumoUtility.Margin.NONE);

        Button refreshBtn = new Button("↻ Refresh", e -> {
            refreshStats();
            recentGrid.getDataCommunicator().reset();
        });
        refreshBtn.addThemeVariants(ButtonVariant.LUMO_TERTIARY);

        HorizontalLayout h = new HorizontalLayout(heading, refreshBtn);
        h.setWidthFull();
        h.setAlignItems(Alignment.BASELINE);
        h.setJustifyContentMode(JustifyContentMode.BETWEEN);
        return h;
    }

    // ── Stat cards ────────────────────────────────────────────────────────────

    /**
     * Returns a {@link VerticalLayout} containing a wrapping row of KPI cards
     * (via {@link FlexLayout}) and a free-traffic progress bar below them.
     * Using {@link FlexLayout} instead of {@code HorizontalLayout} is important
     * because only {@code FlexLayout} exposes {@link FlexLayout#setFlexWrap}.
     */
    private VerticalLayout buildStatCards() {
        applyBadge(totalSpan,   "badge");
        applyBadge(freeSpan,    "badge success");
        applyBadge(chargedSpan, "badge contrast");
        applyBadge(windowsSpan, "badge");
        applyBadge(costSpan,    "badge error");

        FlexLayout cards = new FlexLayout(
                statCard("Total messages",         totalSpan),
                statCard("Free messages ",        freeSpan),
                statCard("Charged messages ",     chargedSpan),
                statCard("Open windows ",          windowsSpan),
                statCard("Est. cost (USD)",          costSpan)
        );
        cards.setFlexWrap(FlexLayout.FlexWrap.WRAP);
        cards.setWidthFull();
        cards.getStyle().set("gap", "var(--lumo-space-m)");

        // Free-ratio bar card
        freeBar.setWidthFull();
        Paragraph barLabel = new Paragraph("Free traffic ratio");
        barLabel.addClassNames(LumoUtility.Margin.NONE, LumoUtility.FontSize.SMALL,
                LumoUtility.TextColor.SECONDARY);
        Div freeBarCard = new Div(barLabel, freeBar);
        freeBarCard.addClassNames(LumoUtility.Padding.MEDIUM, LumoUtility.BorderRadius.MEDIUM,
                LumoUtility.Background.CONTRAST_5);
        freeBarCard.setWidthFull();

        VerticalLayout layout = new VerticalLayout(cards, freeBarCard);
        layout.setPadding(false);
        layout.setSpacing(true);
        layout.setWidthFull();
        return layout;   // ← was previously returning only `cards` (bug: freeBarCard was lost)
    }

    private static void applyBadge(Span span, String theme) {
        span.getElement().getThemeList().add(theme);
        span.addClassNames(LumoUtility.FontSize.XLARGE, LumoUtility.FontWeight.BOLD);
    }

    private Div statCard(String label, Span valueSpan) {
        Paragraph l = new Paragraph(label);
        l.addClassNames(LumoUtility.Margin.NONE, LumoUtility.FontSize.SMALL,
                LumoUtility.TextColor.SECONDARY);
        Div card = new Div(l, valueSpan);
        card.addClassNames(LumoUtility.Padding.MEDIUM, LumoUtility.BorderRadius.MEDIUM,
                LumoUtility.Background.CONTRAST_5);
        card.setWidth("200px");
        return card;
    }

    // ── Quick-send panel ──────────────────────────────────────────────────────

    private Div buildQuickSend() {
        toField.setPlaceholder("+15551234567");
        toField.setWidth("220px");
        textField.setPlaceholder("Hello from WhatsApp!");
        textField.setWidth("400px");

        Button sendBtn = new Button("Send text", e -> doQuickSend());
        sendBtn.addThemeVariants(ButtonVariant.LUMO_PRIMARY, ButtonVariant.LUMO_SUCCESS);

        Paragraph hint = new Paragraph(
                " Cost tip: if a 24-hour service window is open for the recipient, "
                        + "this message is completely free. Otherwise a UTILITY template is used (also free).");
        hint.addClassNames(LumoUtility.FontSize.SMALL, LumoUtility.TextColor.SECONDARY,
                LumoUtility.Margin.NONE);

        HorizontalLayout row = new HorizontalLayout(toField, textField, sendBtn);
        row.setAlignItems(Alignment.END);

        Div card = new Div(new H3("✉️ Quick Send"), row, hint);
        card.addClassNames(LumoUtility.Padding.MEDIUM, LumoUtility.BorderRadius.MEDIUM,
                LumoUtility.Background.CONTRAST_5);
        card.setWidthFull();
        return card;
    }

    private void doQuickSend() {
        String to   = toField.getValue();
        String text = textField.getValue();
        if (to.isBlank() || text.isBlank()) {
            Notification.show("Please fill in both fields.", 3000, Notification.Position.MIDDLE);
            return;
        }
        String tenantId = TenantContext.currentTenantId().orElse("demo");
        try {
            WhatsAppMessage sent = service.sendTextMessage(tenantId, to, text);
            boolean free = sent.freeConversation();
            Notification n = Notification.show(
                    free ? "✅ Sent FREE (service window)" : "✅ Sent (utility template)",
                    4000, Notification.Position.BOTTOM_END);
            n.addThemeVariants(free ? NotificationVariant.LUMO_SUCCESS : NotificationVariant.LUMO_CONTRAST);
            textField.clear();
            refreshStats();
            recentGrid.getDataCommunicator().reset();
        } catch (Exception ex) {
            Notification n = Notification.show("Send failed: " + ex.getMessage(),
                    5000, Notification.Position.MIDDLE);
            n.addThemeVariants(NotificationVariant.LUMO_ERROR);
        }
    }

    // ── Lazy recent-messages grid ─────────────────────────────────────────────

    private Div buildRecentMessages() {
        recentGrid.addColumn(WhatsAppMessage::to)
                .setHeader("To").setAutoWidth(true);
        recentGrid.addColumn(m -> m.type().name())
                .setHeader("Type").setWidth("100px");
        recentGrid.addColumn(m -> m.conversationType().name())
                .setHeader("Category").setWidth("140px");
        recentGrid.addColumn(m -> m.freeConversation() ? "✅ Free" : " Charged")
                .setHeader("Cost").setWidth("110px");
        recentGrid.addColumn(m -> m.status().name())
                .setHeader("Status").setWidth("110px");
        recentGrid.addColumn(m -> truncate(m.content(), 60))
                .setHeader("Content").setFlexGrow(1);

        // ── Lazy data provider (unknown-item-count mode) ──────────────────────
        // setItems(CallbackDataProvider.FetchCallback) fetches exactly one page per
        // scroll-down; no upfront COUNT query is issued.
        recentGrid.setItems(query -> {
            String tenantId = TenantContext.currentTenantId().orElse("demo");
            return service.listMessages(tenantId, query.getOffset(), query.getLimit()).stream();
        });

        recentGrid.setHeight("340px");
        recentGrid.setWidthFull();

        Div card = new Div(new H3(" Recent Messages (lazy)"), recentGrid);
        card.addClassNames(LumoUtility.Padding.MEDIUM, LumoUtility.BorderRadius.MEDIUM,
                LumoUtility.Background.CONTRAST_5);
        card.setWidthFull();
        return card;
    }

    // ── Stats refresh (KPI cards only; grid uses DataCommunicator.reset()) ────

    private void refreshStats() {
        String tenantId = TenantContext.currentTenantId().orElse("demo");
        WhatsAppUsageStats stats = service.getUsageStats(tenantId, YearMonth.now());

        totalSpan.setText(String.valueOf(stats.totalMessages()));
        freeSpan.setText(String.valueOf(stats.freeMessages()));
        chargedSpan.setText(String.valueOf(stats.chargedMessages()));
        windowsSpan.setText(String.valueOf(stats.openWindows()));
        costSpan.setText("$%.4f".formatted(stats.estimatedCostUsd()));

        // ProgressBar range 0–100: pass the percentage value directly
        freeBar.setValue(stats.totalMessages() == 0 ? 100.0 : stats.freePercentage());
    }

    private static String truncate(String s, int max) {
        if (s == null) return "";
        return s.length() > max ? s.substring(0, max) + "…" : s;
    }
}

package com.holonplatform.multitenant.whatsapp.ui.views;

import com.holonplatform.multitenant.whatsapp.config.TenantWhatsAppProperties;
import com.holonplatform.multitenant.whatsapp.ui.WhatsAppManageLayout;
import com.vaadin.flow.component.button.Button;
import com.vaadin.flow.component.button.ButtonVariant;
import com.vaadin.flow.component.html.*;
import com.vaadin.flow.component.notification.Notification;
import com.vaadin.flow.component.notification.NotificationVariant;
import com.vaadin.flow.component.orderedlayout.VerticalLayout;
import com.vaadin.flow.component.textfield.PasswordField;
import com.vaadin.flow.component.textfield.TextField;
import com.vaadin.flow.router.PageTitle;
import com.vaadin.flow.router.Route;
import com.vaadin.flow.theme.lumo.LumoUtility;

/**
 * WhatsApp integration settings view.
 *
 * <p>Displays the current SHARED mode configuration (access token masked),
 * documents how to obtain credentials from Meta Business Manager, and
 * explains the mode difference (SHARED vs DEDICATED).</p>
 *
 * <p>In production, this view would allow per-tenant overrides when
 * {@code TenantWhatsAppProperties.Mode == DEDICATED}.</p>
 */
@Route(value = "whatsapp/settings", layout = WhatsAppManageLayout.class)
@PageTitle("WhatsApp Settings")
public class WhatsAppSettingsView extends VerticalLayout {

    private final TenantWhatsAppProperties properties;

    public WhatsAppSettingsView(TenantWhatsAppProperties properties) {
        this.properties = properties;
        setSizeFull();
        setPadding(true);
        setSpacing(true);
        add(buildSetupGuide(), buildCurrentConfig(), buildCostGuide());
    }

    // ─── Setup guide ──────────────────────────────────────────────────────────

    private Div buildSetupGuide() {
        Div card = new Div();
        card.addClassNames(LumoUtility.Padding.MEDIUM, LumoUtility.BorderRadius.MEDIUM,
                LumoUtility.Background.CONTRAST_5);
        card.setWidthFull();

        card.add(new H2(" WhatsApp Business Cloud API – Setup Guide"));
        card.add(new Paragraph("Follow these steps to connect your Meta WhatsApp Business Account:"));

        UnorderedList steps = new UnorderedList();
        steps.add(li("1. Go to <b>Meta for Developers</b> (developers.facebook.com) → create or select an App."));
        steps.add(li("2. Add the <b>WhatsApp</b> product to your app."));
        steps.add(li("3. Under <b>WhatsApp → API Setup</b>: note your <b>Phone Number ID</b> and <b>WABA ID</b>."));
        steps.add(li("4. Create a <b>System User</b> in Business Manager with <em>MANAGE</em> permissions on the WABA. Copy its permanent token."));
        steps.add(li("5. Set the three properties below in your <code>application.properties</code>."));
        steps.add(li("6. Configure the webhook: Callback URL = <code>https://&lt;your-host&gt;/webhook/whatsapp</code>, subscribe to <b>messages</b>."));
        steps.add(li("7. Set <code>holon.tenant.whatsapp.webhook.verify-token</code> to match the token you entered in Meta."));
        card.add(steps);
        return card;
    }

    // ─── Current config ───────────────────────────────────────────────────────

    private Div buildCurrentConfig() {
        TenantWhatsAppProperties.SharedCredentials creds = properties.getShared();
        boolean configured = creds != null
                && creds.getAccessToken() != null && !creds.getAccessToken().isBlank();

        Div card = new Div();
        card.addClassNames(LumoUtility.Padding.MEDIUM, LumoUtility.BorderRadius.MEDIUM,
                LumoUtility.Background.CONTRAST_5);
        card.setWidthFull();
        card.add(new H3("⚙️ Current Configuration"));

        TextField modeField = new TextField("Mode");
        modeField.setValue(properties.getMode().name());
        modeField.setReadOnly(true);

        TextField phoneField = new TextField("Phone Number ID");
        phoneField.setValue(creds != null && creds.getPhoneNumberId() != null
                ? creds.getPhoneNumberId() : "(not set)");
        phoneField.setReadOnly(true);

        TextField wabaField = new TextField("WABA ID");
        wabaField.setValue(creds != null && creds.getWabaId() != null
                ? creds.getWabaId() : "(not set)");
        wabaField.setReadOnly(true);

        PasswordField tokenField = new PasswordField("Access Token");
        tokenField.setValue(configured ? "••••••••••••••••••" : "(not set)");
        tokenField.setReadOnly(true);
        tokenField.setWidth("400px");

        Paragraph status = new Paragraph(configured
                ? "✅ Connected – messages will be sent via the Meta Cloud API."
                : "⚠ Not configured – running in DEMO mode (messages are only logged).");
        status.addClassNames(configured ? LumoUtility.TextColor.SUCCESS : LumoUtility.TextColor.ERROR);

        Paragraph configHint = new Paragraph(
                "Set credentials in application.properties:\n" +
                "holon.tenant.whatsapp.shared.access-token=EAAG...\n" +
                "holon.tenant.whatsapp.shared.phone-number-id=...\n" +
                "holon.tenant.whatsapp.shared.waba-id=...");
        configHint.getStyle().set("white-space", "pre").set("font-family", "monospace");
        configHint.addClassNames(LumoUtility.FontSize.XSMALL, LumoUtility.TextColor.SECONDARY);

        card.add(status, modeField, phoneField, wabaField, tokenField, configHint);
        return card;
    }

    // ─── Cost reduction guide ─────────────────────────────────────────────────

    private Div buildCostGuide() {
        Div card = new Div();
        card.addClassNames(LumoUtility.Padding.MEDIUM, LumoUtility.BorderRadius.MEDIUM,
                LumoUtility.Background.CONTRAST_5);
        card.setWidthFull();
        card.add(new H3(" Cost Reduction Strategies"));

        UnorderedList tips = new UnorderedList();
        tips.add(li("✅ <b>Leverage service windows</b> – when a customer messages you first, a FREE 24-hour reply window opens. The ConversationWindowTracker ensures all replies within that window are free."));
        tips.add(li("✅ <b>Prefer UTILITY templates</b> – all utility templates are FREE (Meta 2024 pricing). Use them for order confirmations, shipping alerts, reminders, and any transactional content instead of MARKETING."));
        tips.add(li("✅ <b>Avoid unnecessary MARKETING templates</b> – restricted to PROFESSIONAL+ plans and count against the monthly quota. Only use when promotional content is genuinely needed."));
        tips.add(li("✅ <b>Click-to-WhatsApp ads</b> – referral conversations (user clicks a WhatsApp ad) provide one free conversation. Ideal for lead generation without paying per conversation."));
        tips.add(li("✅ <b>SHARED WABA mode</b> – multiple tenants share one phone number, reducing the overhead of maintaining multiple Meta business accounts."));
        tips.add(li("✅ <b>Rate limiting</b> – the built-in TenantRateLimiter prevents accidental bursts that could exhaust quotas or trigger Meta throttling."));
        tips.add(li("✅ <b>Monitor with the Dashboard</b> – the dashboard shows real-time free vs charged ratio, estimated cost, and open windows so you can optimise behaviour continuously."));
        card.add(tips);
        return card;
    }

    // ─── Helpers ──────────────────────────────────────────────────────────────

    private static ListItem li(String html) {
        ListItem item = new ListItem();
        item.getElement().setProperty("innerHTML", html);
        item.addClassNames(LumoUtility.Margin.Bottom.SMALL);
        return item;
    }
}

package com.holonplatform.multitenant.whatsapp.ui.views;

import com.holonplatform.multitenant.TenantContext;
import com.holonplatform.multitenant.whatsapp.TenantWhatsAppService;
import com.holonplatform.multitenant.whatsapp.WhatsAppConversationType;
import com.holonplatform.multitenant.whatsapp.WhatsAppTemplate;
import com.holonplatform.multitenant.whatsapp.ui.WhatsAppManageLayout;
import com.vaadin.flow.component.AttachEvent;
import com.vaadin.flow.component.button.Button;
import com.vaadin.flow.component.button.ButtonVariant;
import com.vaadin.flow.component.grid.Grid;
import com.vaadin.flow.component.html.*;
import com.vaadin.flow.component.notification.Notification;
import com.vaadin.flow.component.notification.NotificationVariant;
import com.vaadin.flow.component.orderedlayout.HorizontalLayout;
import com.vaadin.flow.component.orderedlayout.VerticalLayout;
import com.vaadin.flow.router.PageTitle;
import com.vaadin.flow.router.Route;
import com.vaadin.flow.theme.lumo.LumoUtility;

/**
 * Lists all approved WhatsApp message templates for the current tenant,
 * with colour-coded billing categories and a send-test action.
 *
 * <h3>Template cost at a glance</h3>
 * <ul>
 *   <li> <b>UTILITY</b>   – free (transactional: order updates, reminders)</li>
 *   <li> <b>AUTHENTICATION</b> – charged per message (OTP / verification)</li>
 *   <li> <b>MARKETING</b> – most expensive (promotions, re-engagement)</li>
 * </ul>
 *
 * <p>Tip shown to operators: use UTILITY templates instead of MARKETING wherever
 * the content qualifies as transactional to eliminate per-conversation charges.</p>
 *
 * <h3>Lazy loading</h3>
 * Templates are a small, bounded list fetched from the Meta API (or from the
 * in-memory seed) on {@link #onAttach(AttachEvent)} — not in the constructor.
 * The grid uses the standard eager {@code setItems(list)} because template lists
 * typically contain fewer than 100 items; no scrolling pagination is needed.
 * A "Refresh from Meta API" button re-triggers the fetch on demand.
 */
@Route(value = "whatsapp/templates", layout = WhatsAppManageLayout.class)
@PageTitle("WhatsApp Templates")
public class WhatsAppTemplatesView extends VerticalLayout {

    private final TenantWhatsAppService service;
    private final Grid<WhatsAppTemplate> grid = new Grid<>(WhatsAppTemplate.class, false);

    public WhatsAppTemplatesView(TenantWhatsAppService service) {
        this.service = service;
        setSizeFull();
        setPadding(true);
        setSpacing(true);
        // Constructor: build structure only – no service calls
        add(buildHeader(), buildCostTip(), buildGrid());
    }

    // ── Lazy init ─────────────────────────────────────────────────────────────

    @Override
    protected void onAttach(AttachEvent event) {
        super.onAttach(event);
        refresh();
    }

    private HorizontalLayout buildHeader() {
        H2 heading = new H2(" Message Templates");
        heading.addClassNames(LumoUtility.Margin.NONE);

        Button refreshBtn = new Button("↻ Refresh from Meta API", e -> refresh());
        refreshBtn.addThemeVariants(ButtonVariant.LUMO_TERTIARY);

        HorizontalLayout h = new HorizontalLayout(heading, refreshBtn);
        h.setWidthFull();
        h.setAlignItems(Alignment.BASELINE);
        h.setJustifyContentMode(JustifyContentMode.BETWEEN);
        return h;
    }

    private Div buildCostTip() {
        Div tip = new Div();
        tip.addClassNames(LumoUtility.Padding.MEDIUM, LumoUtility.BorderRadius.MEDIUM,
                LumoUtility.Background.CONTRAST_5);
        tip.add(new Paragraph(
                " Cost optimisation tip: UTILITY templates are free and suitable for any " +
                        "transactional notification (order confirmations, shipping updates, account alerts, " +
                        "appointment reminders). Only use MARKETING templates when you explicitly need to " +
                        "send promotional content. AUTHENTICATION is needed for OTP flows only."));
        return tip;
    }

    private Grid<WhatsAppTemplate> buildGrid() {
        grid.addColumn(WhatsAppTemplate::name).setHeader("Template Name").setAutoWidth(true).setSortable(true);
        grid.addColumn(WhatsAppTemplate::language).setHeader("Language").setWidth("110px");
        grid.addColumn(t -> categoryLabel(t.category())).setHeader("Category (Cost)").setWidth("200px");
        grid.addColumn(WhatsAppTemplate::status).setHeader("Status").setWidth("110px");
        grid.addColumn(t -> t.isFree() ? "✅ Free" : " Charged").setHeader("Billing").setWidth("110px");
        grid.addComponentColumn(t -> buildSendButton(t)).setHeader("Action").setWidth("140px");

        grid.setWidthFull();
        grid.setHeight("500px");
        return grid;
    }

    private Button buildSendButton(WhatsAppTemplate template) {
        Button btn = new Button("Test send");
        btn.addThemeVariants(ButtonVariant.LUMO_SMALL,
                template.isFree() ? ButtonVariant.LUMO_SUCCESS : ButtonVariant.LUMO_ERROR);
        btn.addClickListener(e -> {
            if (!template.isApproved()) {
                Notification.show("Template is not APPROVED by Meta yet.", 3000, Notification.Position.MIDDLE);
                return;
            }
            String tenantId = TenantContext.currentTenantId().orElse("demo");
            try {
                service.sendTemplateMessage(tenantId, "+15550000000",
                        template.name(), template.language(), java.util.Map.of("1", "TestValue"));
                Notification n = Notification.show(
                        "✅ Template '" + template.name() + "' sent to +15550000000",
                        4000, Notification.Position.BOTTOM_END);
                n.addThemeVariants(NotificationVariant.LUMO_SUCCESS);
            } catch (Exception ex) {
                Notification n = Notification.show("Failed: " + ex.getMessage(),
                        5000, Notification.Position.MIDDLE);
                n.addThemeVariants(NotificationVariant.LUMO_ERROR);
            }
        });
        return btn;
    }

    private static String categoryLabel(WhatsAppConversationType cat) {
        if (cat == null) return "–";
        return switch (cat) {
            case UTILITY        -> " UTILITY (free)";
            case AUTHENTICATION -> " AUTHENTICATION (charged)";
            case MARKETING      -> " MARKETING (charged)";
            case SERVICE        -> " SERVICE (free)";
            default             -> cat.name();
        };
    }

    private void refresh() {
        String tenantId = TenantContext.currentTenantId().orElse("demo");
        grid.setItems(service.listTemplates(tenantId));
    }
}
